INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('nature', 'angelus', 'angelus', 'Angelus', NULL, '{"nature":"angelus","description":"Les Angelus descendent de créatures artificielles d’Aèr transcendées par Elynea jusqu’à devenir des individus reliés à l’Arbre de Vie. Leur incarnation terrestre constitue une vraie vie : famille, métier et convictions ne disparaissent pas lorsque reviennent des souvenirs célestes plus anciens. Nature angélique, Sephirah, Archange lié et école séraphique sont des couches distinctes d’une Transcendance qui n’impose ni obéissance automatique des religions humaines ni personnalité unique.","carte":"**ANGELUS · NATURE** — une créature d''Aèr devenue une personne par la Transcendance.\n\n**Voilé (V)** : corps humain, souvenirs intacts. Aucun pouvoir angélique, sauf étiquette V.\n**Semi-Révélé (SR)** : profil SR de ton Sephira. L''Auréole, les Yeux et les pouvoirs subtils s''ouvrent. Un profane voit un humain.\n**Révélé (R)** : profil R de ton Sephira (il remplace le SR). Forme véritable : lumière, ailes d''énergie.\nChanger d''état : 1 PA, sans jet. Tu peux passer directement de V à R.\n\n**Traits gratuits**\n- **Âme transcendée** (V/SR/R) : à la mort de ton incarnation, ton âme rentre au Paradis par l''Arbre de Vie. Ce n''est pas un retour en jeu.\n- **Détachement céleste** (V/SR/R) : +3 contre les effets surnaturels fondés sur une émotion (peur, désir, honte, colère, attachement, séduction). En contrepartie, comprendre d''instinct une émotion complexe ou tue est d''un niveau plus difficile.\n- **Aura** : maximum 3 + Force Mentale permanente (Chérubin +2, Séraphin +4 ; plafonds 8 / 10 / 12). Hors pression, tu peux la remplir entièrement avant une scène importante.\n- **Ouvrir l''Auréole** (SR/R, 1 PA) : +2 Aura (+3 dans un lieu sacré de l''Arbre). Sans jet.\n- **Yeux célestes** (SR/R, 1 PA, 1 Aura, scène) : tu vois les formes véritables, les illusions, les transformations et les dissimulations surnaturelles. Ni Sang, ni PV, ni pensées, ni à travers les murs.\n- **Ailes transcendées** (R, 1 PA, 1 Aura, scène) : +1 Agilité au total, quel que soit le nombre de paires. Pas de vol stationnaire. Les PA déjà tirés ne changent pas.\n- **Impulsion céleste** (R, 1 Aura, avec un Déplacement) : distance doublée, grands obstacles verticaux franchis, chute amortie, terrain difficile ignoré. Tu finis sur un support.\n- **Égide d''Aura** (SR/R, Réaction) : contre une attaque qui vise l''âme, l''esprit ou l''essence, ou faite de puissance divine ou spirituelle, dépense 1 à 3 Aura : −2 dégâts par Aura. Rien contre une balle, une chute ou un feu ordinaire.\n- **Canalisation des prières** et **Sens du Réseau** (SR/R, passifs) : tu recharges mieux en lieu sacré, et tu sens une zone fortement liée à ton Sephira (direction, jamais coordonnées).\n\n**Faiblesses** : pas de malédiction de Nature. Contreparties : la difficulté d''empathie ci-dessus ; un pouvoir qui coupe l''âme de son plan bloque la recharge (l''Aura stockée reste) ; la Lame céleste se paie en PV maximum.\n\n*Référence MJ* : un pouvoir à plusieurs PA engage son Aura dès le premier PA ; si l''action est perdue, l''Aura aussi. Une hausse de Vigueur en R augmente le maximum de PV, jamais les PV actuels.\n\n**Gratuit aussi à la création** : le pouvoir de ta Nature angélique, l''Empreinte et le Don de ton Sephira, le Don de ton Archange, la Faveur de ton Séraphin.\n\n---","traits_gratuits":[{"name":"Âme transcendée","access":"V/SR/R","effect":"À la destruction de l’incarnation, l’âme retourne vers le Paradis par l’Arbre de Vie."},{"name":"Yeux célestes","access":"SR/R","effect":"Perçoit formes véritables, illusions et transformations occultes."},{"name":"Ailes transcendées","access":"R","effect":"Déploie des ailes d’énergie."}],"droits_acquis":"Les talents achetés avant les voies restent acquis ; les règles de voie valent pour les achats suivants (décision 20)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'angelus', 'angelus_voies_communes_tout_angelus', 'Voies communes (tout Angelus)', NULL, '{"nature":"angelus","chemin":["Voies communes (tout Angelus)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_voies_communes_tout_angelus_aureole', 'Auréole', NULL, '{"nature":"angelus","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier I (coûts d''origine 1 et 1). Formule « min(plafond…) » retirée du texte : même résultat."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_commune_pouvoirs_angeliques_talents_communs_reserve_transcendee', 'Réserve transcendée', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R · Passif · acquisition unique","activation":"Passif · acquisition unique","texte_court":"Aura maximum +2, ajouté après le plafond de rang (Angelus 10, Chérubin 12). Une seule fois ; ne remplit pas l''Aura courante.","texte_reference":"Votre maximum d’Aura augmente de 2 après application du plafond de votre rang. Cet achat n’est possible qu’une fois et ne recharge pas l’Aura courante.\n\nMaximum = min(plafond de rang, 3 + Force Mentale permanente + bonus de rang) + 2. Angelus : bonus 0, plafond 8 ; Chérubin : bonus 2, plafond 10. Un bonus temporaire de Compétence ne crée jamais d’Aura. Aucun remplissage automatique de la réserve courante.","lore":"À mesure que la Transcendance s’enracine, l’âme peut contenir davantage de souffle de l’Arbre sans le laisser se disperser. Cette réserve supplémentaire reste bornée par ce que le rang céleste actuel est réellement capable de porter.","groupe_actuel":"Nature commune — pouvoirs angéliques › Talents communs","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_commune_pouvoirs_angeliques_talents_communs_recharge_fulgurante', 'Recharge fulgurante', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"une fois par scène, Ouvrir l''Auréole rend 4 Aura au lieu de 2 (ou de 3). Pas de cumul.","texte_reference":"Une fois par scène, Ouvrir l''Auréole rend 4 Aura au lieu de 2 (ou de 3 dans un lieu sacré). Les valeurs de remplacement ne s''additionnent pas.","lore":"Ouvrir l’Auréole peut parfois provoquer un afflux beaucoup plus vif qu’à l’ordinaire. Une fois la connexion pleinement dégagée, l’Aura revient comme une poussée soudaine plutôt que comme le filet habituel.","groupe_actuel":"Nature commune — pouvoirs angéliques › Talents communs","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_commune_pouvoirs_angeliques_talents_communs_egide_renforcee', 'Égide renforcée', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"chaque Aura dépensée par l''Égide réduit 3 dégâts au lieu de 2 (3 Aura au plus par attaque).","texte_reference":"Chaque point d''Aura dépensé par Égide réduit 3 dégâts au lieu de 2. Maximum 3 Aura par attaque.","lore":"L’Égide devient plus dense lorsque l’Angelus sait mieux convertir l’Aura en rempart immédiat. Chaque parcelle de lumière dépensée absorbe davantage du choc avant de se dissiper.","groupe_actuel":"Nature commune — pouvoirs angéliques › Talents communs","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_voies_communes_tout_angelus_racine', 'Racine', NULL, '{"nature":"angelus","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Liaison céleste remplace Porte du Paradis du livre V6 (projection de l''âme), retirée du site ; coût du livre (2) retenu. Six phrases de lore coupées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_commune_pouvoirs_angeliques_talents_communs_regard_celeste_affine', 'Regard céleste affiné', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"Yeux célestes actifs, +3 pour percer une illusion ou une dissimulation surnaturelle active.","texte_reference":"+3 aux tests destinés spécifiquement à percer une illusion ou une dissimulation surnaturelle active lorsque les Yeux célestes sont déjà actifs.","lore":"Les Yeux célestes apprennent à regarder les coutures d’une fausse apparence. Quand ils sont déjà ouverts, le regard s’attarde sur les incohérences d’une illusion ou d’une dissimulation active jusqu’à rendre son mensonge plus difficile à soutenir.","groupe_actuel":"Nature commune — pouvoirs angéliques › Talents communs","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_commune_pouvoirs_angeliques_talents_communs_sensibilite_mortelle', 'Sensibilité mortelle', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":null,"texte_court":"le Détachement n''augmente plus la difficulté pour comprendre les émotions des mortels. Tu gardes ton +3.","texte_reference":"Le personnage a suffisamment vécu parmi les mortels pour supprimer l''augmentation de difficulté de Détachement céleste lorsqu''il doit comprendre intuitivement leurs émotions. Il conserve son +3 de résistance aux manipulations affectives.","lore":"Vivre parmi les mortels laisse une compréhension que la distance céleste aurait autrement émoussée. L’Angelus reconnaît plus naturellement leurs émotions sans perdre pour autant la résistance que sa propre nature oppose aux manipulations affectives.","groupe_actuel":"Nature commune — pouvoirs angéliques › Talents communs","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_commune_pouvoirs_angeliques_talents_communs_porte_du_paradis', 'Liaison céleste', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura, scène","activation":"1 PA · 1 Aura · scène","texte_court":"tu parles mentalement, à toute distance sur le même monde, avec un autre Angelus connu, consentant et relié à l''Arbre. Messages volontaires seulement : ni pensées, ni sens, ni Aura.","texte_reference":"Pour 1 PA et 1 Aura, établissez jusqu’à la fin de la scène une communication mentale avec un autre Angelus connu, consentant et relié à l’Arbre sur le même monde, quelle que soit la distance. Le lien transmet uniquement les messages volontairement échangés, sans lecture des pensées, partage des sens ni transfert d’Aura.\n\nL’Arbre est un lien métaphysique, pas un territoire que l’on visite. Vous restez dans votre corps et ne déplacez ni votre âme ni votre incarnation. L’interlocuteur doit être réellement connu et accepter l’échange ; aucune réponse automatique d’Elynea ou d’un Archange et aucune connaissance nouvelle ne sont garanties. Une rupture effective de la connexion à l’Arbre interrompt la liaison.","lore":"L’Auréole porte une parole choisie entre deux âmes reliées à l’Arbre, sans transformer ce lien métaphysique en lieu de passage.","groupe_actuel":"Nature commune — pouvoirs angéliques › Talents communs","statut_regle":"correction","changements":"Liaison céleste remplace Porte du Paradis du livre V6 (projection de l''âme), retirée du site ; coût du livre (2) retenu. Six phrases de lore coupées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'angelus', 'angelus_nature_angelique_une_seule_la_seconde_au_rang_cherubin', 'Nature angélique (une seule ; la seconde au rang Chérubin)', NULL, '{"nature":"angelus","chemin":["Nature angélique (une seule ; la seconde au rang Chérubin)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_nature_angelique_une_seule_la_seconde_au_rang_cherubin_lecture_des_ames', 'Lecture des âmes', NULL, '{"nature":"angelus","forme":"progression","forme_lot":"progression (Trône)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":"- **Socle (gratuit)** : Télépathie céleste.","changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_trone_lecture_superficielle', 'Lecture superficielle', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura","activation":null,"texte_court":"Volonté + Maîtrise spirituelle contre Défense occulte. Tu lis la pensée dominante, l''intention immédiate et l''émotion consciente. Un mensonge, seulement si la pensée contredit ce qui est dit.","texte_reference":"Volonté + Maîtrise spirituelle contre Défense occulte. Lire la pensée dominante, l''intention immédiate, l''émotion consciemment ressentie et un mensonge seulement si la pensée réelle contredit directement ce qui est dit à cet instant.","lore":"La surface mentale suffit souvent au Trône. Pensée dominante, intention immédiate et émotion consciente deviennent perceptibles, tandis qu’un mensonge n’apparaît que lorsque l’esprit pense réellement autre chose au même instant.","groupe_actuel":"Nature : Trône","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_trone_lecture_profonde', 'Lecture profonde', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA, 2 Aura","activation":null,"texte_court":"même jet ; tu cherches une information ou un souvenir précis. Le DR fixe la netteté. Il faut savoir ce que l''on cherche.","texte_reference":"Rechercher une information ou un souvenir précis dans l''esprit. Volonté + Maîtrise spirituelle contre Défense occulte ; le DR détermine la netteté. Il faut savoir ce que l''on cherche, pas télécharger l''esprit entier.","lore":"Le Trône plonge dans l’esprit avec une question précise plutôt qu’avec la prétention de tout posséder. Le souvenir recherché apparaît par couches, plus ou moins net selon la résistance et la profondeur à laquelle il fallait descendre.","groupe_actuel":"Nature : Trône","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_nature_angelique_une_seule_la_seconde_au_rang_cherubin_jugement', 'Jugement', NULL, '{"nature":"angelus","forme":"une_porte","forme_lot":"collection à une porte (Trône)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier II (coûts d''origine 2 et 2). Précision : une faute « établie » l''est dans la fiction (aveu, preuve, Lecture des âmes, témoignage), pas par simple soupçon."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_trone_marque_du_trone', 'Marque du Trône', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura","activation":"1 PA · 1 Aura · 100 m · scénario","texte_court":"après avoir observé son âme ou ouvert un lien télépathique, tu marques une cible (Défense occulte si elle résiste). Jusqu''à la fin du scénario, tu reconnais son âme et sens sa direction à 100 m. Une marque à la fois.","texte_reference":"Après observation de l’âme ou lien télépathique, marquez une cible pour 1 PA et 1 Aura, avec opposition occulte si elle résiste. Jusqu’à la fin du scénario, reconnaissez cette âme et percevez sa direction approximative à 100 m maximum ; une seule marque de ce talent à la fois.\n\nLe marquage ne donne ni coordonnées, ni vision à travers les murs ; un isolement spirituel adapté peut en bloquer la perception.","lore":"Après avoir vraiment rencontré une âme, le Trône peut y apposer un sceau de reconnaissance. À distance raisonnable, cette signature demeure identifiable et donne une direction approximative, trace spirituelle plutôt que localisation cartographique.","groupe_actuel":"Nature : Trône","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_trone_anatheme', 'Anathème', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 2 Aura","activation":null,"texte_court":"vise un pouvoir actif que tu as vu fonctionner. Volonté + Maîtrise spirituelle contre Défense occulte : 1 charge pour la scène (−3 à son jet d''activation, ou +1 PA s''il n''a pas de jet). À 2 charges, inutilisable pour la scène. Jamais une Nature, une Empreinte, l''Aura ni un trait passif fondamental.","texte_reference":"Cibler un pouvoir surnaturel actif, précis et identifiable que le Trône a vu fonctionner ou suffisamment analysé. Volonté + Maîtrise spirituelle contre Défense occulte. Une réussite pose 1 charge pour la scène : -3 aux jets d''activation, ou +1 PA à la prochaine utilisation si le pouvoir n''a aucun jet. À 2 charges, le pouvoir devient inaccessible jusqu''à la fin de la scène. Ne vise jamais une Nature, une Empreinte, l''Aura, l''Auréole, l''immortalité d''âme ou une propriété fondamentale purement passive.","lore":"Le Trône condamne un pouvoir précis après l’avoir vu prendre forme. Chaque charge d’Anathème inscrit cette manifestation parmi les choses que l’autorité céleste désapprouve, jusqu’à pouvoir lui fermer totalement l’accès pour la scène.","groupe_actuel":"Nature : Trône","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_trone_justice_veritable', 'Justice véritable', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura","activation":null,"texte_court":"contre une cible dont une faute grave envers l''Arbre est établie, jusqu''à trois alliés gagnent +3 à leur première action contre elle, jusqu''au début de ton prochain round.","texte_reference":"Désigner une cible dont une faute grave vis-à-vis des lois ou intérêts célestes a été réellement établie. Jusqu''au début du prochain round du Trône, jusqu''à trois alliés gagnent +3 à leur première action directement dirigée contre cette cible.","lore":"Le Trône ne distribue pas sa justice sans faute établie. Une cible dont l’acte grave est reconnu devient cependant un point de convergence pour les alliés, chacun voyant plus clairement où diriger sa prochaine action contre elle.","groupe_actuel":"Nature : Trône","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_trone_heresie_condamnee', 'Hérésie condamnée', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, Réaction, 3 Aura, 1/scène ; requiert Anathème","activation":null,"texte_court":"quand la cible utilise un pouvoir déjà chargé, même jet. Réussite : l''effet est annulé contre toi et le pouvoir prend sa 2e charge. DR 2+ : tu protèges aussi une seconde cible visée.","texte_reference":"Réaction lorsque la cible utilise un pouvoir portant déjà une charge d''Anathème. Volonté + Maîtrise spirituelle contre Défense occulte. Réussite : l''effet est annulé contre le Trône et le pouvoir reçoit sa seconde charge, devenant inaccessible pour la scène. DR 2+ : le Trône peut protéger une seconde cible de l''effet si elle était également visée.","lore":"Lorsqu’un pouvoir déjà condamné ose se manifester encore, le Trône peut transformer l’avertissement en jugement. L’effet se brise contre l’autorité céleste et la voie employée se trouve fermée pour le reste de la confrontation.","groupe_actuel":"Nature : Trône","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_nature_angelique_une_seule_la_seconde_au_rang_cherubin_purification', 'Purification', NULL, '{"nature":"angelus","forme":"progression","forme_lot":"progression (Vertu)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":"- **Socle (gratuit)** : Purification.","changements":"mention « réservé à la passe Fléaux » retirée (chantier interne). Redites d''Envie coupées. Orgueil suit le site (« Compétence sociale adaptée ») et non le livre (« Autorité/Influence »)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_vertu_apaisement_profond', 'Apaisement profond', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"après une Purification réussie, la cible gagne +3 jusqu''à la fin de la scène contre la même famille d''émotions.","texte_reference":"Après une Purification réussie, la cible gagne +3 jusqu''à la fin de la scène contre les effets de la même famille émotionnelle que celle purifiée.","lore":"La Vertu ne se contente pas d’arracher une émotion hostile : elle laisse derrière elle un espace plus difficile à recoloniser. Ce qui vient d’être purifié reconnaît mieux la même famille d’emprise lorsqu’elle tente de revenir.","groupe_actuel":"Nature : Vertu","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_vertu_purification_de_l_ame', 'Purification de l''âme', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA, 2 Aura","activation":"2 PA · 2 Aura · opposition","texte_court":"Volonté + Maîtrise spirituelle contre la Puissance d''une malédiction, d''une possession ou d''une altération hostile de l''âme ; réussite, elle est retirée. Jamais une Nature ni une Marque fondamentale. Ne retire aucun point de Corruption.","texte_reference":"Pour 2 PA et 2 Aura, opposez Volonté + Maîtrise spirituelle à la Puissance d’une malédiction, possession ou autre altération hostile de l’âme pour la retirer. Cela ne supprime pas une Nature ou une Marque fondamentale et ne retire pas, à lui seul, des points de Corruption.\n\nPrérequis Apaisement profond conservé ; règles de purification chiffrée de la Corruption réservées à la passe Fléaux.","lore":"La Vertu cherche l’altération qui s’est accrochée à l’âme sans confondre cette intrusion avec l’identité profonde de la créature. Malédiction, possession ou lien hostile peuvent être défaits ; une Nature véritable n’est pas une souillure à laver.","groupe_actuel":"Nature : Vertu","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_vertu_chatiment_capital', 'Châtiment capital', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":"2 PA · 3 Aura · 1/scène","texte_court":"tu réinjectes ce que tu as absorbé (il faut l''avoir absorbé dans la fiction) dans toi ou un allié consentant : un Péché pour la scène. Purifier le Châtiment retire bonus et contreparties.","texte_reference":"Pour 2 PA et 3 Aura, une fois par scène, appliquez à vous-même ou à un allié consentant un des sept Péchés pour la scène, avec ses avantages et contreparties. Envie accorde +2 dans une Compétence réellement observée, sans copier ses talents ou ses secrets.\n\nLes six autres variantes sont conservées. Le +2 d’Envie est un bonus temporaire de pratique : il ne transfère ni talent, ni connaissance secrète, ni prérequis biologique. Purifier le Châtiment retire ensemble les avantages et les contreparties. La ressource fictionnelle absorbée par la Vertu reste requise.","lore":"La Vertu peut condenser en puissance utile ce qu’elle a dû comprendre des Péchés. L’état choisi devient une tension assumée, avec son bénéfice et son prix indissociables jusqu’à ce qu’une vraie purification les emporte ensemble.","groupe_actuel":"Nature : Vertu","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_nature_angelique_une_seule_la_seconde_au_rang_cherubin_porter_l_ame', 'Porter l''âme', NULL, '{"nature":"angelus","forme":"une_porte","forme_lot":"collection à une porte (Vertu)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"phrases sur la règle des Réactions coupées."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_vertu_fardeau_partage', 'Fardeau partagé', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 1 PA, 1 Aura, 10 m","activation":"Réaction · 1 PA · 1 Aura · 10 m","texte_court":"un allié perçu qui rate une résistance émotionnelle la relance et garde le second résultat. S''il échoue encore, −3 à tes actions de calme ou de concentration jusqu''à la fin de ton prochain round.","texte_reference":"Pour 1 PA en Réaction et 1 Aura, faites relancer la résistance émotionnelle ratée d’un allié perçu à 10 m maximum, qui conserve le second résultat. S’il échoue encore, vous subissez −3 aux actions exigeant calme ou concentration jusqu’à la fin de votre prochain round.\n\nUne seule relance de Talent par test ; aucune relance en cascade. Le PA découle de la règle générale des Réactions. Aucune nouvelle limitation par scène n’est ajoutée.","lore":"Porter le fardeau d’un autre signifie parfois absorber une part de son désordre. La Vertu offre à l’allié une seconde chance de tenir face à l’émotion hostile, sachant que l’échec reviendra frapper sa propre capacité à rester calme.","groupe_actuel":"Nature : Vertu","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_vertu_soin_de_l_ame', 'Soin de l''âme', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA, 2 Aura","activation":null,"texte_court":"Volonté + Maîtrise spirituelle, difficulté selon la gravité. La cible récupère 3 + DR PV ; ou tu stabilises, accélères une lésion grave, soignes une blessure spirituelle. Saturation de l''Arbre.","texte_reference":"Volonté + Maîtrise spirituelle, difficulté selon la gravité. Sur réussite, la cible récupère 3 + DR PV ; peut également stabiliser, accélérer la réparation d''une lésion grave ou agir sur une blessure explicitement spirituelle. La Saturation de guérison de l''Arbre s''applique.","lore":"Le soin d’une Vertu travaille à l’endroit où chair et âme cessent d’être séparables. La lumière peut refermer une blessure, stabiliser un mourant ou soutenir une lésion spirituelle, toujours sous les limites que l’Arbre impose à la guérison répétée.","groupe_actuel":"Nature : Vertu","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_nature_angelique_une_seule_la_seconde_au_rang_cherubin_lame', 'Lame', NULL, '{"nature":"angelus","forme":"progression","forme_lot":"progression (Domination)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":"- **Socle (gratuit)** : Lame céleste.","changements":"historique de coût retiré du texte. Le PA reste celui du site (1 ; le livre disait 2)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_domination_arme_de_l_executeur', 'Arme de l''Exécuteur', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"une fois par round, remodeler la Lame (épée, lance, arc, fusil…). DGT inchangés ; Compétence de la forme.","texte_reference":"Une fois par round, remodeler gratuitement la Lame : épée, lance, arc, fusil, etc. DGT inchangé ; utiliser la Compétence correspondant à la forme. L''apparence peut être adaptée à la mission sans conférer de statistiques supplémentaires.","lore":"La Lame céleste d’une Domination n’a pas à rester prisonnière d’une forme cérémonielle. Elle suit le besoin de l’exécution — lame, hampe ou arme de tir — tout en demeurant la même autorité armée sous des silhouettes différentes.","groupe_actuel":"Nature : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_domination_misericorde', 'Miséricorde', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"une fois par round, quand une attaque céleste touche : cible à 50 % de ses PV maximum ou moins, +2 DGT ; à 25 % ou moins, +4 à la place.","texte_reference":"Une fois par round, lorsqu''une attaque céleste de la Domination touche : cible à 50 % PV ou moins = +2 DGT ; cible à 25 % PV ou moins = +4 DGT à la place. Les deux ne s''additionnent pas.","lore":"La Miséricorde d’une Domination est sévère : elle consiste à finir plus vite ce qui est déjà brisé. Plus la cible approche de l’effondrement, plus la Lame trouve dans cette faiblesse une raison de frapper sans détour.","groupe_actuel":"Nature : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_domination_mise_a_mort', 'Mise à mort', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 3 Aura, 1/scène ; requiert Miséricorde","activation":"1 PA · 3 Aura · 1/scène","texte_court":"attaque de Lame contre une cible à 25 % de ses PV maximum ou moins : +6 DGT (remplace Miséricorde), 3 Protection ignorée. Si elle tombe à 0 ou moins, aucune stabilisation avant ton prochain round.","texte_reference":"Une fois par scène, pour 1 PA et 3 Aura, attaquez avec la Lame céleste une cible à 25 % de ses PV maximum ou moins : +6 DGT et 3 Protection ignorée. Le +6 remplace celui de Miséricorde ; une cible tombée à 0 ou moins ne peut être stabilisée avant le début de votre prochain round.\n\nLe coût passe de 2 à 1 PA ; coût PTV, condition de PV, pénétration et effet de stabilisation conservés. Le non-cumul explicite avec Miséricorde évite un +10 de même intention. Aucune destruction automatique d’âme ou négation d’une sauvegarde de Nature supérieure.","lore":"Lorsque l’adversaire est déjà au bord de la chute, la Domination peut faire de son attaque une exécution. Toute la logique de la Lame se resserre vers le coup décisif, sans pour autant abolir une protection qui appartient réellement à une Nature supérieure.","groupe_actuel":"Nature : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_nature_angelique_une_seule_la_seconde_au_rang_cherubin_traque', 'Traque', NULL, '{"nature":"angelus","forme":"une_porte","forme_lot":"collection à une porte (Domination)","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"deux talents au palier I. Phrase « Remplace le +3 après Impulsion » retirée (renvoi à une version disparue). Le cumul des pénétrations (Marque −2, Azrael −3, Mise à mort −3) reste possible : létalité voulue."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_domination_marque_de_l_assassin', 'Marque de l''Assassin', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 PA, 1 Aura","activation":"1 PA · 1 Aura · scène","texte_court":"tu marques une cible visible pour la scène. À chaque round, la première attaque réussie contre elle, quel qu''en soit l''auteur, ignore 2 Protection. Une marque à la fois.","texte_reference":"Pour 1 PA et 1 Aura, marquez une cible visible jusqu’à la fin de la scène. La première attaque réussie contre elle à chaque round ignore 2 points de Protection ; la marque reste en place et vous ne pouvez en maintenir qu’une.\n\nUne seule attaque bénéficie de la marque dans un round, quel que soit son auteur ; plusieurs exemplaires équivalents ne s’additionnent pas. Le bonus n’est pas une pénétration permanente de toutes les armes.","lore":"La Domination choisit une proie et laisse sur elle une marque de condamnation martiale. La première ouverture trouvée contre cette cible paraît déjà connue de la Lame, qui traverse mieux la protection avant que la marque ne s’éteigne.","groupe_actuel":"Nature : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_domination_vision_du_mal', 'Vision du Mal', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura","activation":null,"texte_court":"pour la scène, jusqu''à trois alliés voient ce que tu vois d''une cible : sa forme réelle, l''illusion qui la cache, son vrai corps parmi des doubles.","texte_reference":"Choisir une cible ou manifestation surnaturelle perçue. Jusqu''à la fin de la scène, jusqu''à trois alliés voient à travers les perceptions transcendées de la Domination concernant cette cible : forme réelle malgré l''Hologramme, illusion qui la dissimule, vrai corps parmi des doubles si la Domination le distingue. Ils n''obtiennent pas des Yeux célestes universels.","lore":"La Domination partage avec ses alliés ce que son regard transcendé a déjà découvert sur une cible précise. L’apparence fausse perd alors son avantage devant le groupe, sans offrir à chacun un pouvoir général de révélation sur tout le reste du monde.","groupe_actuel":"Nature : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'nature_domination_poursuite_celeste', 'Poursuite céleste', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, Réaction, 1 PA, 1 Aura, 1/round","activation":"Réaction · 1 PA · 1 Aura · 1/round","texte_court":"quand une cible que tu as marquée s''éloigne par un déplacement physique, tu l''attaques avec ta Lame avant son départ, si elle est à portée.","texte_reference":"Une fois par round, lorsqu’une cible que vous avez marquée s’éloigne volontairement par un déplacement physique, vous pouvez l’attaquer avec votre Lame céleste avant son départ pour 1 PA en Réaction et 1 Aura. La cible doit être à portée au moment de l’attaque ; aucune poursuite après une téléportation déjà résolue.\n\nRemplace le +3 après Impulsion, sans ajouter d’attaque gratuite ni renouveler les limites d’Ambidextre. Les marques personnelles de la Domination ou du Trône peuvent servir si elles sont réellement actives.","lore":"Une cible marquée ne devrait pas pouvoir acheter sa survie avec quelques mètres. L’impulsion céleste devient poursuite, et l’Angelus transforme le terrain gagné en angle d’attaque avant que la proie n’ait recréé sa distance.","groupe_actuel":"Nature : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira', 'Les dix Sephiroth (un seul Sephira)', NULL, '{"nature":"angelus","chemin":["Les dix Sephiroth (un seul Sephira)"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_kether_la_couronne', 'Carte · KETHER, la Couronne', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"notes coupées. Le rapport proposait de fusionner Synchronisation avec « Prendre la tête » de l''Aseryn : refusé (charte). Ressort propre déjà présent : la Synchronisation passe par le Nœud, sans un mot, et coûte de l''Aura."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_kether_la_couronne_facette_domination_injonction_celeste', 'Injonction céleste', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura","activation":null,"texte_court":"Charisme + Autorité contre Défense occulte : un ordre simple, accompli à la prochaine occasion. Ni suicide ni mutilation grave.","texte_reference":"Charisme + Autorité contre Défense occulte. Un ordre simple doit être accompli à la prochaine occasion disponible. Pas de suicide ni mutilation majeure.","lore":"Kether donne à un ordre simple la force d’une place incontestable dans la hiérarchie de l’instant. La cible garde une volonté propre, mais son prochain mouvement cherche spontanément à satisfaire l’injonction reçue.","groupe_actuel":"Les dix Sephiroth › Kether — La Couronne › Facette : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_kether_la_couronne_facette_domination_decret_de_la_couronne', 'Décret de la Couronne', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura","activation":null,"texte_court":"une interdiction simple pour la scène. À chaque tentative directe de la violer, nouvelle Défense occulte ; une réussite brise le Décret.","texte_reference":"Imposer une interdiction simple pour la scène. À chaque tentative directe de violation, nouvelle Défense occulte ; une réussite brise définitivement le Décret.","lore":"La Couronne énonce une interdiction comme une règle de souveraineté. Celui qui veut la violer peut encore lutter contre elle, mais chaque tentative doit d’abord briser l’autorité céleste qui affirme que ce geste n’a pas lieu d’être.","groupe_actuel":"Les dix Sephiroth › Kether — La Couronne › Facette : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_kether_la_couronne_facette_domination_une_seule_voix', 'Une seule voix', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":null,"texte_court":"une même Injonction touche toutes les cibles choisies à 15 m qui comprennent l''ordre.","texte_reference":"Une même Injonction touche toutes les cibles choisies dans un rayon de 15 m capables de comprendre l''ordre.","lore":"La Couronne cesse de parler à un individu et s’adresse à l’espace social tout entier. Ceux qui comprennent la même phrase reçoivent simultanément son poids, comme une assemblée saisie par une seule voix venue d’au-dessus d’elle.","groupe_actuel":"Les dix Sephiroth › Kether — La Couronne › Facette : Domination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_kether_la_couronne_facette_conscience_regard_partage', 'Regard partagé', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura, scène","activation":"1 PA · 1 Aura · scène","texte_court":"tu perçois ce qu''un membre consentant du Nœud partage de ses sens. Ni ses Compétences, ni ses pouvoirs.","texte_reference":"Pour 1 PA et 1 Aura, percevez les sensations volontairement partagées d’un membre consentant de votre Nœud jusqu’à la fin de la scène. Le lien reste limité à la portée du Nœud et ne vous transfère pas ses compétences ni l’usage de ses pouvoirs.\n\nLe Nœud initial coûte séparément 1 PA et 1 Aura ; ses trois participants incluent le créateur. Recevoir une perception n’accorde pas une action au partenaire.","lore":"Le lien de Kether ouvre momentanément les sens d’un compagnon consentant. L’Angelus ne devine pas ce qu’il voit : il reçoit réellement son point de vue, avec les limites et les angles propres au corps qui perçoit.","groupe_actuel":"Les dix Sephiroth › Kether — La Couronne › Facette : Conscience","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_kether_la_couronne_facette_conscience_aucun_angle_mort', 'Aucun angle mort', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"tant qu''un membre du Nœud perçoit clairement une menace, aucun autre membre n''est Surpris par elle.","texte_reference":"Tant qu''un membre du Nœud perçoit clairement une menace, aucun autre membre ne peut être considéré comme Surpris par cette menace.","lore":"Le Nœud de Kether ne partage pas seulement des informations : il partage l’urgence. Dès qu’un membre voit clairement une menace, les autres sentent assez sa présence pour ne plus pouvoir être surpris comme s’ils l’ignoraient totalement.","groupe_actuel":"Les dix Sephiroth › Kether — La Couronne › Facette : Conscience","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_kether_la_couronne_facette_conscience_conscience_distribuee', 'Conscience distribuée', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura, 1/scène","activation":"1 PA · 2 Aura · 1/scène","texte_court":"jusqu''à la fin de la scène, les membres du Nœud utilisent la meilleure Défense occulte passive du groupe contre les effets mentaux ou perceptifs, si elle s''applique à l''effet.","texte_reference":"Pour 1 PA et 2 Aura, une fois par scène, les membres de votre Nœud peuvent utiliser la meilleure Défense occulte passive du groupe contre les effets mentaux ou perceptifs jusqu’à la fin de la scène. Cela ne remplace pas les caractéristiques de leurs Défenses actives et cesse pour un membre dont le lien est suspendu.\n\nLa meilleure valeur doit être réellement applicable à l’effet considéré ; les résistances conditionnelles ne deviennent pas des bonus universels. La durée de scène remplace la protection d’une seule Réaction.","lore":"Dans Kether, plusieurs consciences liées peuvent faire front comme une architecture commune. Lorsqu’une intrusion mentale ou perceptive frappe l’un d’eux, la stabilité du membre le plus solide peut servir de rempart au reste du Nœud.","groupe_actuel":"Les dix Sephiroth › Kether — La Couronne › Facette : Conscience","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_kether_la_couronne_facette_unite_assistance_parfaite', 'Assistance parfaite', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"les membres du Nœud s''Assistent en combat s''ils ont la Compétence. +2, jamais cumulatif.","texte_reference":"Les membres du Nœud peuvent s''Assister en combat s''ils possèdent réellement la Compétence appropriée. Toujours +2, jamais cumulatif.","lore":"Dans le Nœud, l’aide n’arrive plus une seconde trop tard parce que chacun combat isolément. Les compétences réellement partagées s’imbriquent jusque dans la mêlée et permettent aux partenaires de soutenir le geste utile sans brouiller son exécution.","groupe_actuel":"Les dix Sephiroth › Kether — La Couronne › Facette : Unité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_kether_la_couronne_facette_unite_synchronisation', 'Synchronisation', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura, 1/scène","activation":"1 PA · 2 Aura · 1/scène","texte_court":"jusqu''à deux autres membres du Nœud agissent juste après toi dans la passe. Ils doivent avoir une action dans cette passe, la paient et perdent leur ancien emplacement.","texte_reference":"Une fois par scène, pour 1 PA et 2 Aura, jusqu’à deux autres membres de votre Nœud peuvent agir immédiatement après vous dans la passe en cours. Ils doivent encore avoir leur action dans cette passe, la paient normalement et perdent leur ancien emplacement : aucune action supplémentaire.\n\nRemplace la micro-mobilité par une modification d’ordre d’action. Une passe ne peut être rejouée et une action déjà accomplie n’est pas récupérée.","lore":"Kether fait disparaître les maladresses qui naissent entre alliés pourtant coordonnés. Pendant un court instant, plusieurs membres se déplacent comme s’ils avaient répété exactement cette circulation ensemble.","groupe_actuel":"Les dix Sephiroth › Kether — La Couronne › Facette : Unité","statut_regle":"correction","changements":"notes coupées. Le rapport proposait de fusionner Synchronisation avec « Prendre la tête » de l''Aseryn : refusé (charte). Ressort propre déjà présent : la Synchronisation passe par le Nœud, sans un mot, et coûte de l''Aura."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_kether_la_couronne_facette_unite_un_pour_tous', 'Un pour tous', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 3 Aura, 1/scène","activation":null,"texte_court":"quand un membre du Nœud rate une Défense occulte, un autre membre peut subir l''effet à sa place s''il est une cible valide.","texte_reference":"Lorsqu''un membre lié échoue à une Défense occulte, un autre membre peut subir l''effet à sa place s''il constitue une cible valide.","lore":"L’unité de Kether peut aller jusqu’à accepter la blessure de l’esprit destinée à un autre. Un membre du Nœud se place sur le chemin de l’effet immatériel et en devient volontairement le destinataire réel.","groupe_actuel":"Les dix Sephiroth › Kether — La Couronne › Facette : Unité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_hokhma_la_sagesse', 'Carte · HOKHMA, la Sagesse', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun (voir question 4)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hokhma_la_sagesse_facette_sagesse_clarte', 'Clarté', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 Aura","activation":null,"texte_court":"une fois par round, avant un test intellectuel, Prendre son temps sans délai.","texte_reference":"Une fois par round, avant un test intellectuel, bénéficier de l''effet Prendre son temps sans délai supplémentaire.","lore":"La sagesse de Hokhma n’accélère pas la pensée : elle lui donne immédiatement l’espace d’une réflexion posée. Même sous pression, l’Angelus peut considérer un problème intellectuel comme s’il avait eu le temps de l’examiner proprement.","groupe_actuel":"Les dix Sephiroth › Hokhma — La Sagesse › Facette : Sagesse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hokhma_la_sagesse_facette_sagesse_consequence_probable', 'Conséquence probable', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura","activation":null,"texte_court":"face à un choix immédiat entre options comprises, le MJ dit la conséquence immédiate la plus probable de l''une d''elles. Pas une prophétie.","texte_reference":"Face à une décision immédiate entre plusieurs options réellement comprises, le MJ indique la conséquence immédiate la plus probable d''une option choisie. Ce n''est pas une prophétie lointaine.","lore":"Lorsque plusieurs choix sont réellement compris, Hokhma éclaire la première conséquence qui les suit. Ce regard reste proche du présent : une chaîne d’avenir trop longue redeviendrait conjecture plutôt que sagesse.","groupe_actuel":"Les dix Sephiroth › Hokhma — La Sagesse › Facette : Sagesse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hokhma_la_sagesse_facette_sagesse_vision_sereine', 'Vision sereine', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 3 Aura, 1/scène","activation":"1 PA · 3 Aura · 1/scène","texte_court":"confronte ton plan aux indices connus. Le MJ désigne une hypothèse que ces indices contredisent et une vérification concrète ; +3 à la première tentative de vérifier. Sans contradiction accessible, le MJ le dit.","texte_reference":"Une fois par scène, pour 1 PA et 3 Aura, confrontez votre plan aux indices connus : le MJ indique une hypothèse contredite par ces indices et une vérification concrète possible. La première tentative pour effectuer cette vérification gagne +3.\n\nIl n’est plus nécessaire d’avoir découvert soi-même que le plan est faux. Aucune information impossible à déduire, fausse piste créée artificiellement ou solution automatique ; sans contradiction accessible, le MJ le signale.","lore":"Découvrir que l’on s’est trompé n’est pas une humiliation pour Hokhma mais un point de départ. L’Angelus peut retrouver dans les données déjà accessibles le détail mal lu qui avait entraîné tout le raisonnement dans une mauvaise direction.","groupe_actuel":"Les dix Sephiroth › Hokhma — La Sagesse › Facette : Sagesse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hokhma_la_sagesse_facette_purete_dissipation', 'Dissipation', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura","activation":"1 PA · 1 Aura","texte_court":"Volonté + Maîtrise spirituelle contre une pollution spirituelle ou un effet impur mineur : il se dissipe. Ne retire aucune Corruption.","texte_reference":"Pour 1 PA et 1 Aura, opposez Volonté + Maîtrise spirituelle à une pollution spirituelle ou un effet impur mineur pour le dissiper. Ce talent ne retire pas directement de points de Corruption et ne modifie aucune Nature fondamentale.","lore":"Hokhma reconnaît dans une souillure spirituelle un désordre qui peut être défait. L’Angelus cherche son principe de maintien puis le dissipe, tant que l’altération n’appartient pas aux fondations mêmes de la créature.","groupe_actuel":"Les dix Sephiroth › Hokhma — La Sagesse › Facette : Pureté","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hokhma_la_sagesse_facette_purete_cercle_de_purete', 'Cercle de pureté', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 PA, 2 Aura","activation":null,"texte_court":"pour la scène, les alliés à 5 m gagnent +3 contre la possession, la corruption et la mutation surnaturelle hostile.","texte_reference":"Pour la scène, les alliés à 5 m gagnent +3 contre possession, corruption et mutation surnaturelle hostile.","lore":"Autour de l’Angelus, la Pureté de Hokhma trace un espace où certaines intrusions trouvent moins de prise. Corruption, possession et mutation hostile doivent franchir une clarté partagée par ceux qui restent proches.","groupe_actuel":"Les dix Sephiroth › Hokhma — La Sagesse › Facette : Pureté","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hokhma_la_sagesse_facette_purete_exorcisme_lumineux', 'Exorcisme lumineux', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 PA, 3 Aura, 1/scène, 5 m","activation":"3 PA · 3 Aura · 1/scène · 5 m","texte_court":"jusqu''à trois hôtes perçus. Un seul jet, comparé à la Puissance de chaque possession ou parasite identifié : chaque réussite l''expulse sans blesser l''hôte. L''entité n''est pas détruite.","texte_reference":"Une fois par scène, pour 3 PA et 3 Aura, tentez de libérer jusqu’à trois hôtes perçus à 5 m de possessions ou de parasites spirituels identifiés. Comparez votre même jet à chaque Puissance : chaque réussite expulse l’intrus sans blesser l’hôte, mais ne détruit pas l’entité ni une Nature.\n\nLa portée de groupe et l’absence de dommage d’expulsion différencient le talent d’une purification individuelle. Plusieurs intrus distincts sur un même hôte restent des effets distincts, pas une purge universelle.","lore":"Une présence accrochée à une âme est contrainte de se montrer comme étrangère. Hokhma sépare l’hôte du parasite et force la frontière entre eux, sans prétendre convertir une Nature véritable en maladie guérissable.","groupe_actuel":"Les dix Sephiroth › Hokhma — La Sagesse › Facette : Pureté","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hokhma_la_sagesse_facette_magie_lecture_occulte', 'Lecture occulte', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura","activation":null,"texte_court":"identifier la famille d''un phénomène magique visible (illusion, transformation, invocation, malédiction…).","texte_reference":"Identifier la famille générale d''un phénomène explicitement magique visible : illusion, transformation, invocation, malédiction, etc.","lore":"La Sagesse distingue les grandes familles de l’occulte comme un naturaliste reconnaît des traces. Une manifestation visible porte dans sa forme les signes d’une illusion, d’une invocation, d’une métamorphose ou d’une malédiction.","groupe_actuel":"Les dix Sephiroth › Hokhma — La Sagesse › Facette : Magie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hokhma_la_sagesse_facette_magie_contre_forme', 'Contre-forme', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 2 Aura","activation":null,"texte_court":"un effet magique te cible directement : +3 à la Défense. Réussite : tu comprends son mécanisme général.","texte_reference":"Lorsqu''un effet magique prend directement l''Angelus pour cible, +3 à la Défense appropriée. En cas de réussite, comprendre aussi le mécanisme général de l''effet.","lore":"Hokhma répond à la magie par la compréhension. Lorsqu’un effet vient chercher directement l’Angelus, sa structure devient plus facile à repousser et laisse derrière elle assez d’indices pour révéler la logique générale qui l’animait.","groupe_actuel":"Les dix Sephiroth › Hokhma — La Sagesse › Facette : Magie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hokhma_la_sagesse_facette_magie_silence_magique', 'Silence magique', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 3 Aura, 1/scène","activation":null,"texte_court":"un effet explicitement magique (Mageius, rituel, pouvoir dit magique) qui te vise ou vise un allié à 10 m : Volonté + Maîtrise spirituelle contre son résultat. Victoire : annulé avant résolution.","texte_reference":"Lorsqu''un effet explicitement magique (Mageius, rituel magique, pouvoir qualifié de magie) est lancé à portée de perception, Volonté + Maîtrise spirituelle contre son résultat. Victoire : effet annulé avant résolution. Ne contre pas automatiquement tous les pouvoirs surnaturels.","lore":"Hokhma peut opposer au sort en train de naître une compréhension assez nette pour en casser l’architecture. Le silence qui suit n’annule pas toute Vérité : il vise précisément ce qui s’est construit comme magie.","groupe_actuel":"Les dix Sephiroth › Hokhma — La Sagesse › Facette : Magie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_bina_la_comprehension', 'Carte · BINA, la Compréhension', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"« règle proposée » retiré (l''opposition du site est gardée). Deux exemples ajoutés à l''Entrave. Différence avec Réalité verrouillée (Malkhouth) gardée : Bina choisit un procédé, dont l''invisibilité ; Malkhouth bloque ensemble intangibilité et téléportation."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_bina_la_comprehension_facette_intellect_modele_mental', 'Modèle mental', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"après 1 PA d''analyse, +3 au prochain test lié au problème observé.","texte_reference":"Après 1 PA d''analyse, +3 au prochain test directement lié au problème observé.","lore":"L’Angelus construit dans son esprit une représentation nette du problème observé, avec ses forces, ses contraintes et ses points de rupture. Une fois le modèle stabilisé, l’action cesse d’être un pari aveugle.","groupe_actuel":"Les dix Sephiroth › Bina — La Compréhension › Facette : Intellect","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_bina_la_comprehension_facette_intellect_simulation', 'Simulation', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura, 1/scène","activation":"1 PA · 2 Aura · 1/scène","texte_court":"avec un allié, prépare un risque précis et sa réponse. S''il survient dans la scène, la personne désignée fait gratuitement la Défense active ou la manipulation simple prévue.","texte_reference":"Pour 1 PA et 2 Aura, une fois par scène, préparez avec un allié un risque précis et sa réponse. S’il survient pendant cette scène, le participant désigné peut effectuer gratuitement une Défense active ou une manipulation simple correspondant à cette réponse.\n\nUn seul risque, une seule réponse et une seule utilisation ; le bénéficiaire peut être l’Angelus. Aucun bonus +3 en supplément : le bénéfice est la Réaction préparée sans PA, pas une attaque gratuite ni un tour supplémentaire. Le déclencheur doit être matériellement réalisable ; pas d’immunité à un danger imprévisible.","lore":"Avant de lancer un plan, l’Angelus en fait jouer mentalement une version réduite et choisit le risque qu’il surveillera. Si ce risque survient réellement, il n’est plus une surprise mais une scène déjà traversée en pensée.","groupe_actuel":"Les dix Sephiroth › Bina — La Compréhension › Facette : Intellect","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_bina_la_comprehension_facette_intellect_planification_superieure', 'Planification supérieure', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1/scénario, sans Aura","activation":"Préparation réelle · 1/scénario · sans Aura","texte_court":"après une vraie préparation, nomme avec le MJ deux risques de l''opération. Jusqu''à trois participants briefés relancent chacun un échec non narratif lié à ces risques pendant l''exécution.","texte_reference":"Une fois par scénario, après une préparation réelle, identifiez avec le MJ deux risques prévisibles de l’opération. Jusqu’à trois participants briefés peuvent chacun relancer un échec non narratif répondant à l’un de ces risques pendant la scène d’exécution, en gardant le second résultat.\n\nCoût d’Aura inchangé : aucun. Le plan et les participants sont fixés avant l’opération ; pas de connaissance de secrets impossibles à anticiper et pas de cumul de relances sur un même test.","lore":"Bina enseigne que beaucoup d’échecs commencent bien avant l’instant où ils deviennent visibles. En préparant réellement l’action, l’Angelus distingue les deux faiblesses les plus plausibles qu’un esprit informé pouvait déjà anticiper.","groupe_actuel":"Les dix Sephiroth › Bina — La Compréhension › Facette : Intellect","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_bina_la_comprehension_facette_destin_pressentiment', 'Pressentiment', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 1 Aura","activation":null,"texte_court":"un danger perceptible survient soudain : +3 à ta première Défense ou action pour l''éviter.","texte_reference":"Lorsqu''un danger perceptible mais soudain survient, +3 à la première Défense ou action pour l''éviter.","lore":"Chez Bina, le danger projette parfois son ombre une fraction de seconde avant d’arriver. Cette avance minuscule suffit à faire tourner la tête, lever une garde ou choisir l’unique pas qui évite le pire.","groupe_actuel":"Les dix Sephiroth › Bina — La Compréhension › Facette : Destin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_bina_la_comprehension_facette_destin_bifurcation', 'Bifurcation', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 Aura, 1/scène","activation":null,"texte_court":"relance ton d10e et garde le second. Compte comme modification surnaturelle du jet.","texte_reference":"Relancer son d10e et conserver le second résultat. Compte comme la modification surnaturelle du jet.","lore":"Bina laisse entrevoir le point précis où une décision pourrait encore bifurquer. L’Angelus ne remonte pas le temps : il reconnaît simplement que l’issue du geste n’était pas aussi close qu’elle le paraissait.","groupe_actuel":"Les dix Sephiroth › Bina — La Compréhension › Facette : Destin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_bina_la_comprehension_facette_destin_fenetre_du_destin', 'Fenêtre du destin', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 1 PA, 3 Aura, 1/scène, 10 m","activation":"Réaction · 1 PA · 3 Aura · 1/scène · 10 m","texte_court":"un allié perçu vient de rater (échec non narratif) : il relance son d10e et garde le second. Compte comme son talent de relance.","texte_reference":"Une fois par scène, pour 1 PA en Réaction et 3 Aura, un allié perçu à 10 m qui vient de subir un échec non narratif peut relancer son d10e et conserver le second résultat. Il ne repaie pas l’action, mais cette relance compte dans la limite d’un seul Talent de relance par test.\n\nLa restriction « échec de 3 points ou moins » est supprimée ; l’action est rejugée avant application de ses conséquences, ce n’est plus une seconde action distincte qui contourne la règle des relances.","lore":"Un échec étroit peut révéler qu’une autre voie restait encore ouverte. La Compréhension de Bina montre à l’allié où reprendre son action sans prétendre effacer ce qui vient réellement de se produire.","groupe_actuel":"Les dix Sephiroth › Bina — La Compréhension › Facette : Destin","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_bina_la_comprehension_facette_limitations_entrave_conceptuelle', 'Entrave conceptuelle', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura","activation":null,"texte_court":"Volonté + Maîtrise spirituelle contre Défense occulte : −3 à une famille cohérente d''actions (tirer, fuir, mentir…) jusqu''à la fin de son prochain round.","texte_reference":"Volonté + Maîtrise spirituelle contre Défense occulte : -3 à une famille cohérente d''actions jusqu''à la fin du prochain round.","lore":"Bina peut donner une frontière conceptuelle à ce qu’une cible tente d’accomplir. Ce n’est pas le corps qui devient lourd : toute une famille de gestes paraît soudain devoir franchir une définition qui refuse de céder.","groupe_actuel":"Les dix Sephiroth › Bina — La Compréhension › Facette : Limitations","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_bina_la_comprehension_facette_limitations_limite_imposee', 'Limite imposée', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura","activation":null,"texte_court":"désigne un Talent surnaturel observé ; opposition réussie, il est inutilisable jusqu''au début de ton prochain round. Une fois par scène par talent et par cible.","texte_reference":"Désigner un Talent surnaturel observé. Sur opposition réussie, il ne peut pas être utilisé jusqu''au début du prochain round de l''Angelus. Une même cible ne peut subir Limite imposée qu''une fois par scène sur un même Talent.","lore":"Après avoir vu un pouvoir et compris sa forme, l’Angelus peut en désigner la limite. La manifestation reste connue de son porteur, mais quelque chose dans Bina lui refuse brièvement le passage vers le réel.","groupe_actuel":"Les dix Sephiroth › Bina — La Compréhension › Facette : Limitations","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_bina_la_comprehension_facette_limitations_frontiere_de_bina', 'Frontière de Bina', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":"2 PA · 3 Aura · 1/scène","texte_court":"frontière de 10 m de rayon pour la scène, qui interdit au choix la téléportation, l''intangibilité ou l''invisibilité surnaturelle. Pour y user de ce procédé, alliés compris, il faut battre ton jet d''installation (Volonté + Maîtrise spirituelle + 1d10e). Réussir permet la tentative, sans détruire le champ.","texte_reference":"Pour 2 PA et 3 Aura, une fois par scène, établissez pour la scène une frontière de 10 m de rayon interdisant au choix téléportation, intangibilité ou invisibilité surnaturelle. Toute tentative d’y utiliser le procédé choisi doit vaincre votre jet d’installation, alliés compris.\n\nJet d’installation : Volonté + Maîtrise spirituelle + 1d10e ; la tentative oppose le jet approprié de sa source. La victoire permet cette tentative, pas la destruction automatique du champ. La frontière n’arrache pas une Nature passive et ne rematérialise pas rétroactivement un corps déjà intangible. L’ajout d’une opposition est une règle proposée.","lore":"La Compréhension devient loi locale. Dans l’espace marqué, Bina affirme qu’une possibilité précise — disparaître, se dématérialiser ou sauter hors du lieu — n’appartient momentanément plus aux évidences du monde.","groupe_actuel":"Les dix Sephiroth › Bina — La Compréhension › Facette : Limitations","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_hesed_la_misericorde', 'Carte · HESED, la Miséricorde', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"phrases de garde-fou coupées. Fréquence du site (1/scène ; livre : 1/scénario)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hesed_la_misericorde_facette_misericorde_epargner', 'Épargner', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, Réaction","activation":null,"texte_court":"quand tu ferais passer une cible sous 0 PV, tu peux la laisser à 0 PV, Stabilisée.","texte_reference":"Lorsque l''Angelus inflige des dégâts qui feraient passer une cible sous 0 PV, il peut volontairement la laisser à 0 PV, Stabilisée.","lore":"Même lorsqu’il est celui qui frappe, un Angelus de Hesed peut choisir le point où la violence s’arrête. La cible tombe, vaincue et vivante, parce que la Miséricorde demeure un choix jusque dans le geste décisif.","groupe_actuel":"Les dix Sephiroth › Hesed — La Miséricorde › Facette : Miséricorde","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hesed_la_misericorde_facette_misericorde_grace_accordee', 'Grâce accordée', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura, 5 m","activation":"1 PA · 2 Aura · 5 m","texte_court":"jusqu''à trois alliés perçus perdent un état de douleur, de fatigue ou de choc dont la cause a cessé. Aucun PV rendu.","texte_reference":"Pour 1 PA et 2 Aura, retirez à jusqu’à trois alliés perçus à 5 m un état temporaire de douleur, fatigue ou choc dont la cause active a cessé. Aucun PV n’est rendu et les minima imposés par les blessures ou un effet encore actif demeurent.\n\nLa différence nouvelle est le secours de groupe ; pas une guérison biologique définitive ni une suppression de toutes les blessures.","lore":"Quand la cause destructrice a cessé, Hesed peut demander au corps d’abandonner la réaction qui lui survivait encore. Douleur, choc ou épuisement se desserrent, non par négation de la blessure, mais parce qu’ils n’ont plus besoin de gouverner l’instant.","groupe_actuel":"Les dix Sephiroth › Hesed — La Miséricorde › Facette : Miséricorde","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hesed_la_misericorde_facette_misericorde_refuge_de_hesed', 'Refuge de Hesed', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":null,"texte_court":"pendant un round, jusqu''à trois alliés proches qui franchiraient leur seuil de Mort restent à 0 PV, Agonisants, une fois chacun. Un nouveau coup peut les tuer.","texte_reference":"Pendant un round, jusqu''à trois alliés proches qui devraient franchir leur seuil de Mort sont laissés à 0 PV, Agonisants, une seule fois chacun. Un nouveau coup peut les tuer normalement.","lore":"La Miséricorde de Hesed retient plusieurs vies exactement au bord où elles allaient basculer. Elle ne les rend ni saines ni sûres : elle refuse simplement que ce souffle soit le dernier tant qu’un secours reste encore possible.","groupe_actuel":"Les dix Sephiroth › Hesed — La Miséricorde › Facette : Miséricorde","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hesed_la_misericorde_facette_guerison_portee_bienfaisante', 'Portée bienfaisante', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"tes soins angéliques au contact portent à 5 m sur une cible visible. Coût et soin inchangés.","texte_reference":"Les pouvoirs de soin angélique du personnage normalement limités au contact peuvent être utilisés jusqu''à 5 m sur une cible visible. Le coût et la quantité de soin ne changent pas.","lore":"La bonté de Hesed n’a pas toujours besoin d’une main posée sur la plaie. Le lien de soin franchit quelques mètres et atteint une personne visible, comme si la distance comptait moins que la volonté explicite de secourir.","groupe_actuel":"Les dix Sephiroth › Hesed — La Miséricorde › Facette : Guérison","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hesed_la_misericorde_facette_guerison_reconstruction', 'Reconstruction', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, +1 Aura","activation":null,"texte_court":"après un soin angélique, 1 Aura de plus rend utilisable une fonction perdue par blessure (bras fracturé, œil lésé, poumon perforé…) pour la scène ou jusqu''à une prise en charge. Aucun PV.","texte_reference":"Après un soin angélique réussi, dépenser 1 Aura supplémentaire pour restaurer une fonction corporelle précise rendue inutilisable par les blessures : bras fracturé, œil lésé mais présent, poumon perforé, jambe incapable de soutenir le poids, etc. Aucun PV supplémentaire n''est rendu ; la blessure existe encore mais la fonction redevient utilisable pour la scène ou jusqu''à une prise en charge réelle.","lore":"Hesed peut rendre à un organe blessé sa fonction avant d’avoir effacé toute la lésion. Le membre tient, l’œil recommence à servir ou le poumon reprend son travail, grâce fragile qui ne dispense pas d’une véritable guérison ensuite.","groupe_actuel":"Les dix Sephiroth › Hesed — La Miséricorde › Facette : Guérison","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hesed_la_misericorde_facette_guerison_miracle_de_chair', 'Miracle de chair', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 Aura, 1/scénario","activation":null,"texte_court":"après un soin angélique, tu restaures une partie du corps gravement détruite ou perdue depuis très peu, si une continuité biologique demeure. Aucun PV.","texte_reference":"Après un soin angélique réussi, restaurer une partie corporelle gravement détruite ou très récemment perdue si une continuité biologique raisonnable demeure. Aucun paquet de PV supplémentaire n''est rendu.","lore":"La guérison de Hesed se souvient de la forme complète du vivant. Lorsque suffisamment de chair subsiste encore, cette mémoire peut guider une reconstruction que la médecine ordinaire aurait jugée hors de portée.","groupe_actuel":"Les dix Sephiroth › Hesed — La Miséricorde › Facette : Guérison","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hesed_la_misericorde_facette_creativite_inspiration', 'Inspiration', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 Aura","activation":null,"texte_court":"+3 à une action réellement créative (artistique, technique ou intellectuelle).","texte_reference":"+3 à une action réellement créative : artistique, technique ou intellectuelle.","lore":"La Miséricorde peut aussi prendre la forme d’un souffle créateur. Un artiste, un ingénieur ou un penseur sent soudain sa propre intention se clarifier et ose la solution qu’il n’arrivait pas encore à formuler.","groupe_actuel":"Les dix Sephiroth › Hesed — La Miséricorde › Facette : Créativité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hesed_la_misericorde_facette_creativite_idee_feconde', 'Idée féconde', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura","activation":"1 PA · 2 Aura","texte_court":"après un bref échange sur un problème créatif réel, jusqu''à trois alliés font leur prochaine tentative liée avec Prendre son temps sans délai (avant la fin de la scène).","texte_reference":"Pour 1 PA et 2 Aura, après un bref échange sur un problème créatif réel, jusqu’à trois alliés bénéficient de Prendre son temps sans délai sur leur prochaine tentative directement liée au problème. Les connaissances et moyens matériels nécessaires restent requis.\n\nL’avantage expire à la fin de la scène. Aucune seconde application équivalente sur un même test et aucun bonus de +3 ajouté arbitrairement à Prendre son temps.","lore":"Hesed féconde une idée déjà travaillée au lieu de la faire tomber du ciel. Après avoir partagé le problème, l’allié retrouve l’espace mental d’une longue réflexion sans que le monde autour de lui doive réellement s’arrêter.","groupe_actuel":"Les dix Sephiroth › Hesed — La Miséricorde › Facette : Créativité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hesed_la_misericorde_facette_creativite_etincelle_nouvelle', 'Étincelle nouvelle', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 3 Aura, 1/scène","activation":"1 PA · 3 Aura · 1/scène","texte_court":"le MJ indique une approche inhabituelle réalisable avec tes moyens. Le premier test qui la met en œuvre gagne +2 DR s''il réussit (max 5). Toi ou un allié qui la comprend.","texte_reference":"Une fois par scène, pour 1 PA et 3 Aura, le MJ indique une approche inhabituelle réalisable avec vos connaissances et moyens disponibles. Le premier test directement destiné à la mettre en œuvre gagne 2 DR s’il réussit, maximum DR 5.\n\nNe convertit pas un échec en réussite et ne crée aucun matériel, savoir ou nouveau pouvoir. La piste peut bénéficier à l’Angelus ou à un allié qui la comprend réellement.","lore":"Hesed ouvre une porte latérale dans un problème dont les pièces sont déjà présentes. L’Angelus ne reçoit pas une réponse impossible à connaître ; il voit l’usage inattendu mais réalisable de ce que le groupe possède réellement.","groupe_actuel":"Les dix Sephiroth › Hesed — La Miséricorde › Facette : Créativité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_gueburah_la_force', 'Carte · GUEBURAH, la Force', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"phrase finale incompréhensible (« La Réaction spécialisée… ») retirée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_gueburah_la_force_facette_force_puissance_celeste', 'Puissance céleste', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 Aura","activation":null,"texte_court":"+3 aux tests de force brute, de portage, d''enfoncement et de lutte pour la scène.","texte_reference":"+3 aux tests de force brute, portage, enfoncement et lutte physique pour la scène.","lore":"Gueburah n’ajoute pas des muscles étrangers : elle révèle toute la puissance que cette incarnation peut réellement porter. Soulever, retenir ou briser devient l’expression directe d’une Sephirah qui ne doute pas de sa force.","groupe_actuel":"Les dix Sephiroth › Gueburah — La Force › Facette : Force","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_gueburah_la_force_facette_force_briseur', 'Briseur', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R","activation":null,"texte_court":"tes attaques physiques contre objets et structures ignorent 3 Armure.","texte_reference":"Les attaques physiques contre objets et structures ignorent 3 Armure.","lore":"Gueburah voit moins un mur qu’une résistance à vaincre. L’Angelus frappe les structures à l’endroit où force, matière et assemblage cessent de se soutenir mutuellement, ouvrant la voie par la puissance plutôt que par la finesse.","groupe_actuel":"Les dix Sephiroth › Gueburah — La Force › Facette : Force","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_gueburah_la_force_facette_force_force_irresistible', 'Force irrésistible', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 1 PA, 3 Aura, 1/scène","activation":"1 PA · 3 Aura · 1/scène","texte_court":"jusqu''à la fin de la scène, aucun effet de Puissance inférieure à 21 ne te renverse ni ne te déplace tant que tes appuis tiennent. Une attaque physique réussie de la scène gagne +3 DGT, au lieu du +2 d''Impact.","texte_reference":"Une fois par scène, pour 1 PA et 3 Aura, vous ne pouvez être renversé ou déplacé de force par un effet de Puissance inférieure à 21 tant que vos appuis existent, jusqu’à la fin de la scène. Une attaque physique réussie de la scène gagne +3 DGT, à la place du +2 d’Impact de Gueburah s’il aurait été utilisé.\n\nLe +3 ne devient pas un bonus à toutes les attaques. Détruire l’appui, un effondrement ou une force majeure ne sont pas niés. La référence 21 reprend l’échelle commune « majeur » ; les effets ordinaires incapables de déplacer les appuis n’arrachent pas le personnage.","lore":"La Force céleste transforme le corps en point fixe pour un instant. Ce qui tente de renverser l’Angelus rencontre une présence presque immuable, tandis que son propre coup part avec l’élan d’une masse qu’on ne déplace pas.","groupe_actuel":"Les dix Sephiroth › Gueburah — La Force › Facette : Force","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_gueburah_la_force_facette_justice_retribution', 'Rétribution', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 1 Aura","activation":null,"texte_court":"une cible visible blesse volontairement un allié : ta première action contre elle avant la fin du prochain round gagne +3.","texte_reference":"Lorsqu''une cible visible blesse volontairement un allié, la première action du personnage contre cet agresseur avant la fin du prochain round gagne +3.","lore":"Une violence commise sous les yeux de Gueburah crée une réponse immédiate. L’agresseur vient lui-même de désigner la personne vers laquelle la Force doit se tourner, et l’Angelus exploite cette faute avant qu’elle ne se dissolve dans le chaos du combat.","groupe_actuel":"Les dix Sephiroth › Gueburah — La Force › Facette : Justice","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_gueburah_la_force_facette_justice_proportion', 'Proportion', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"SR/R","activation":"Sans PA ni Aura supplémentaires","texte_court":"quand tu mets hors combat un agresseur identifié par une attaque que tu contrôles, tu peux le laisser à 0 PV, Stabilisé. Sans PA ni Aura.","texte_reference":"Lorsque vous mettez hors combat un agresseur identifié par une attaque directement contrôlée, vous pouvez le laisser à 0 PV, Stabilisé. Ce choix ne coûte ni PA supplémentaire ni Aura et ne contrôle pas les victimes d’une explosion ou d’un danger indirect.\n\nCoût proposé : 1 PTV au lieu de 2 ; l’identité judiciaire et la condition d’agresseur sont conservées. On n’ajoute pas une action de combat ni une immunité aux dégâts ultérieurs.","lore":"La justice de Gueburah sait distinguer vaincre de tuer. Face à un agresseur établi, l’Angelus peut retenir l’ultime violence et faire de sa supériorité la preuve qu’une neutralisation suffisait.","groupe_actuel":"Les dix Sephiroth › Gueburah — La Force › Facette : Justice","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_gueburah_la_force_facette_justice_sentence_de_force', 'Sentence de force', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":null,"texte_court":"attaque occulte DGT 12 contre une cible dont la responsabilité dans une violence grave est établie. Sinon, aucun effet.","texte_reference":"Contre une cible dont la responsabilité dans une violence grave a été établie : attaque occulte DGT 12. Sans culpabilité correspondante : aucun effet.","lore":"La sentence de Gueburah n’existe que lorsque la responsabilité a déjà un poids réel. Alors la Force frappe la faute autant que le corps ; sans violence coupable à juger, la puissance céleste ne trouve simplement rien à condamner.","groupe_actuel":"Les dix Sephiroth › Gueburah — La Force › Facette : Justice","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_gueburah_la_force_facette_guerre_ordre_tactique', 'Ordre tactique', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura","activation":null,"texte_court":"un allié gagne +3 à sa prochaine action de combat conforme à ton ordre.","texte_reference":"Un allié gagne +3 à sa prochaine action de combat cohérente avec l''ordre donné.","lore":"Un ordre tactique juste arrive au moment où l’allié peut encore l’exploiter. Gueburah condense l’expérience du combat en une instruction brève qui éclaire immédiatement la meilleure manière de poursuivre l’affrontement.","groupe_actuel":"Les dix Sephiroth › Gueburah — La Force › Facette : Guerre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_gueburah_la_force_facette_guerre_formation_celeste', 'Formation céleste', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 2 Aura, scène","activation":"1 PA · 2 Aura · scène","texte_court":"jusqu''à trois alliés proches : +3 à leur première Défense active physique de chaque round, tant que chacun reste à 3 m d''un autre membre. PA de défense dus.","texte_reference":"Pour 1 PA et 2 Aura, coordonnez jusqu’à trois alliés proches pour la scène : leur première Défense active physique de chaque round gagne +3 tant qu’ils restent chacun à 3 m d’un autre membre de la formation. Les PA de défense restent dus et les gênes ordinaires qu’ils se causent mutuellement sont ignorées.\n\nPas de cumul avec une protection circonstancielle substantiellement équivalente ; la formation n’annule ni explosion ni tir traversant réellement un corps allié.","lore":"La guerre de Gueburah est une discipline collective. Des alliés entraînés à suivre l’Angelus se déplacent comme les éléments d’une même formation, chacun sachant instinctivement quel espace les autres vont tenir.","groupe_actuel":"Les dix Sephiroth › Gueburah — La Force › Facette : Guerre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_gueburah_la_force_facette_guerre_redeploiement', 'Redéploiement', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":"2 PA · 3 Aura · 1/scène","texte_court":"jusqu''à trois alliés à 10 m choisissent chacun un Déplacement complet immédiat, ou une Défense active physique gratuite avant ton prochain round.","texte_reference":"Une fois par scène, pour 2 PA et 3 Aura, jusqu’à trois alliés à 10 m choisissent chacun entre un Déplacement complet immédiat et une Défense active physique gratuite avant votre prochain round. Chaque allié n’utilise qu’une option, sans attaque gratuite ni réserve générale de PA.\n\nUn déplacement reste physiquement possible et une défense ne devient pas autorisée en Surprise par ce seul effet. La Réaction spécialisée ne déclenche pas un nouveau gain de PA.","lore":"La ligne de bataille se recompose avant que l’adversaire n’ait compris qu’elle était en train de bouger. Quelques compagnons gagnent l’instant nécessaire pour se replacer, comme si la volonté de Gueburah avait déjà redessiné le front.","groupe_actuel":"Les dix Sephiroth › Gueburah — La Force › Facette : Guerre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_tiph_ereth_la_beaute', 'Carte · TIPH''ERETH, la Beauté', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"« proposition explicite de clarification » coupée ; coûts inchangés (question 2). Don de soi suit le site (5 dégâts ; le livre disait 3)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_tiph_ereth_la_beaute_facette_foi_certitude', 'Certitude', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 Aura","activation":null,"texte_court":"les effets mécaniques d''une peur ou d''un doute surnaturel sur toi cessent jusqu''à la fin du prochain round.","texte_reference":"Supprimer temporairement les effets mécaniques de peur ou doute surnaturel sur soi jusqu''à la fin du prochain round.","lore":"La foi de Tiph’Ereth n’est pas l’absence de peur mais le refus de lui céder l’autorité. Pendant un instant, le doute surnaturel peut hurler sans modifier le choix que l’Angelus a déjà décidé de tenir.","groupe_actuel":"Les dix Sephiroth › Tiph''Ereth — La Beauté › Facette : Foi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_tiph_ereth_la_beaute_facette_foi_foi_partagee', 'Foi partagée', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura, scène","activation":"1 PA · 2 Aura · scène","texte_court":"jusqu''à trois alliés perçus à 10 m gagnent +3 contre la peur, le désespoir et les contraintes qui veulent briser leur volonté.","texte_reference":"Pour 1 PA et 2 Aura, jusqu’à trois alliés perçus à 10 m gagnent +3 pour résister à peur, désespoir et contraintes visant à briser leur volonté jusqu’à la fin de la scène. Ce bonus ne se cumule pas avec une résistance affective équivalente déjà applicable.","lore":"Une conviction partagée devient chaleur de groupe. Ceux qui restent près de l’Angelus retrouvent dans cette foi assez de sens commun pour que peur, désespoir et abandon ne parlent plus avec une voix unique.","groupe_actuel":"Les dix Sephiroth › Tiph''Ereth — La Beauté › Facette : Foi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_tiph_ereth_la_beaute_facette_foi_miracle_de_conviction', 'Miracle de conviction', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 3 Aura, 1/scénario","activation":null,"texte_court":"un allié échoue de 3 points ou moins à une action indispensable à la cause commune : réussite DR 0.","texte_reference":"Lorsqu''un allié échoue de 3 points ou moins à une action directement indispensable à la cause partagée, transformer l''échec en réussite DR 0. Compte comme modification surnaturelle du résultat.","lore":"Quand un compagnon manque de très peu l’acte indispensable à une cause réellement commune, Tiph’Ereth peut faire peser toute la conviction du groupe dans l’instant. Le geste franchit alors juste le seuil nécessaire, sans se transformer en triomphe spectaculaire.","groupe_actuel":"Les dix Sephiroth › Tiph''Ereth — La Beauté › Facette : Foi","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_tiph_ereth_la_beaute_facette_devotion_lien_devoue', 'Lien dévoué', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":null,"texte_court":"une personne consentante. Tant qu''elle reste dans la même région, tu sais si elle est vivante, inconsciente, gravement blessée ou en danger immédiat. Pas sa position.","texte_reference":"Choisir une personne consentante. Tant qu''elle reste dans la même région générale, connaître intuitivement si elle est vivante, inconsciente, gravement blessée ou en danger immédiat. Pas de position précise.","lore":"Une personne consentante peut devenir un point constant dans la beauté de Tiph’Ereth. La distance efface les détails mais pas les grandes ruptures : vie, inconscience, blessure grave ou danger immédiat continuent de résonner dans le lien.","groupe_actuel":"Les dix Sephiroth › Tiph''Ereth — La Beauté › Facette : Dévotion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_tiph_ereth_la_beaute_facette_devotion_intercession', 'Intercession', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 2 Aura","activation":null,"texte_court":"un effet immatériel cible ton lié (Lien dévoué) à portée de perception : tu deviens la cible à sa place, si l''effet peut t''affecter.","texte_reference":"Lorsqu''un effet immatériel cible le lié à portée de perception, l''Angelus peut devenir la cible à sa place si l''effet peut l''affecter.","lore":"La dévotion refuse de regarder un être lié subir seul une atteinte de l’âme. L’Angelus s’offre comme destination de l’effet et assume volontairement ce qui cherchait quelqu’un d’autre.","groupe_actuel":"Les dix Sephiroth › Tiph''Ereth — La Beauté › Facette : Dévotion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_tiph_ereth_la_beaute_facette_devotion_communion', 'Communion', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 10 m","activation":"1 PA · transfert de 1 à 3 Aura · 10 m","texte_court":"confie jusqu''à 3 de tes Aura à un allié consentant. Un Angelus les reçoit dans sa réserve ; un autre reçoit pour la scène une Égide prêtée : en Réaction (PA normal), −2 dégâts spirituels par Aura confiée. Une Égide prêtée par personne.","texte_reference":"Pour 1 PA, confiez jusqu’à 3 de vos Aura à un allié consentant à 10 m : un Angelus les reçoit dans la limite de sa réserve, un autre personnage reçoit une Égide prêtée pour la scène. Cette Égide ne peut servir qu’à absorber 2 dégâts spirituels par Aura confiée, avec le PA normal de Réaction.\n\nCoût conservé à 3 PTV : c’est l’ouverture aux autres Natures qui justifie le prix. Une Égide prêtée par personne à la fois, non cumulable ; elle n’emploie pas Égide renforcée du donneur, ne recharge pas un Mageius, ne protège pas des balles et ne peut être transférée de nouveau. L’Aura est réellement retirée du donneur ; aucune restitution d’un reste expiré.","lore":"Tiph’Ereth permet à deux Angelus de partager leur souffle céleste aussi concrètement qu’on partage une réserve d’eau. Ce qui rejoint l’autre quitte réellement le donneur, acte de dévotion où l’énergie devient relation.","groupe_actuel":"Les dix Sephiroth › Tiph''Ereth — La Beauté › Facette : Dévotion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_tiph_ereth_la_beaute_facette_sacrifice_offrande', 'Offrande', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Sans PA · 1 PV · 1/round","texte_court":"une fois par scène, sans PA, perds 1 PV irréductible : +2 Aura (sans dépasser le maximum). Ce PV ne revient pas avant la fin de la scène.","texte_reference":"Une fois par round, sans dépenser de PA, perdez 1 PV irréductible pour récupérer 2 Aura, sans dépasser votre maximum. Ce PV ne peut être récupéré avant la fin de la scène.\n\nLe caractère gratuit est une proposition explicite de clarification. Les dégâts restent réels et ne sont ni absorbés par Égide ni rendus par la fin d’un effet ; la connexion coupée ne remplit pas gratuitement la réserve. Une seule Offrande par round, pas par action.","lore":"L’Angelus peut nourrir sa lumière avec sa propre vitalité. Le sang ou la douleur deviennent une offrande immédiate à l’Arbre, échange véritable dont la blessure reste jusqu’à ce que la scène ait fini d’exiger son tribut.","groupe_actuel":"Les dix Sephiroth › Tiph''Ereth — La Beauté › Facette : Sacrifice","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_tiph_ereth_la_beaute_facette_sacrifice_don_de_soi', 'Don de soi', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 1 PA, 1 Aura, 10 m","activation":"Réaction · 1 PA · 1 Aura · 10 m","texte_court":"prends jusqu''à 5 des dégâts finaux d''un allié perçu. Irréductibles pour toi ; pas de seconde redirection.","texte_reference":"Pour 1 PA en Réaction et 1 Aura, prenez jusqu’à 5 des dégâts finaux d’un allié perçu à 10 m à sa place. Ces dégâts sont irréductibles pour vous et ne peuvent pas être transmis une seconde fois.\n\nLes dégâts sont répartis après les réductions de la victime ; aucune double application d’Armure, Égide ou d’une autre redirection sur le même dommage. Ce talent ne remplace pas les règles de Mort.","lore":"Le sacrifice de Tiph’Ereth commence par accepter qu’une blessure puisse changer de destinataire. L’Angelus prend volontairement sur sa propre chair une part du dommage qui allait frapper son allié, et rien ne vient ensuite adoucir ce prix.","groupe_actuel":"Les dix Sephiroth › Tiph''Ereth — La Beauté › Facette : Sacrifice","statut_regle":"correction","changements":"« proposition explicite de clarification » coupée ; coûts inchangés (question 2). Don de soi suit le site (5 dégâts ; le livre disait 3)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_tiph_ereth_la_beaute_facette_sacrifice_sacrifice_lumineux', 'Sacrifice lumineux', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, Réaction, 1/scénario","activation":null,"texte_court":"un allié visible devrait mourir : tu vides ton Aura et perds 5 PV irréductibles ; il reste à 0 PV, Agonisant. Tu peux payer même si cela te tue.","texte_reference":"Lorsqu''un allié visible devrait mourir : vider toute son Aura et subir 5 PV irréductibles. L''allié reste à 0 PV, Agonisant. L''Angelus peut payer même si les 5 PV le tuent.","lore":"Tiph’Ereth pousse le don de soi jusqu’à l’extrême : garder un autre au bord de la mort même si la facture doit tuer celui qui l’intercède. L’Aura se vide, la chair paie, et pourtant un souffle demeure chez celui qui allait partir.","groupe_actuel":"Les dix Sephiroth › Tiph''Ereth — La Beauté › Facette : Sacrifice","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_nesah_la_victoire', 'Carte · NESAH, la Victoire', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"note « le coût passe de 2 à 1 PTV » retirée ; coût d''origine 2 gardé (question 3). Comparaison avec Sensibilité mortelle coupée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_nesah_la_victoire_facette_succes_transformer_l_essai', 'Transformer l''essai', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 Aura","activation":null,"texte_court":"après une réussite, +1 DR (max DR 3).","texte_reference":"Après une réussite, augmenter le DR de 1, maximum DR 3.","lore":"La Victoire ne change pas un échec en miracle ; elle approfondit une réussite qui existe déjà. L’instant favorable s’ouvre un peu davantage et laisse au personnage un résultat plus solide que celui qu’il avait d’abord arraché.","groupe_actuel":"Les dix Sephiroth › Nesah — Là Victoire › Facette : Succès","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_nesah_la_victoire_facette_succes_dynamique_victorieuse', 'Dynamique victorieuse', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"après une action importante réussie, ta prochaine action différente qui poursuit exactement le même objectif gagne +3.","texte_reference":"Après avoir réussi une action importante, la prochaine action différente mais poursuivant exactement le même objectif gagne +3.","lore":"Nesah aime l’élan qui naît d’une victoire déjà acquise. Une action réussie ouvre la suivante lorsque toutes deux poursuivent réellement le même but, comme si le succès avait créé sa propre trajectoire.","groupe_actuel":"Les dix Sephiroth › Nesah — Là Victoire › Facette : Succès","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_nesah_la_victoire_facette_succes_inarretable', 'Inarrêtable', NULL, '{"nature":"angelus","cout":3,"cout_actuel":2,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 3 Aura, 1/scène","activation":"1 PA · 3 Aura · 1/scène","texte_court":"jusqu''à la fin de la scène, ton action longue garde ses PA et ses progrès malgré une interruption ou un échec intermédiaire ; tu la reprends dès que possible. Un échec final reste un échec.","texte_reference":"Une fois par scène, pour 1 PA et 3 Aura, conservez les PA et progrès déjà investis dans une action longue malgré une interruption extérieure ou un échec intermédiaire, jusqu’à la fin de la scène. Vous pouvez la reprendre dès que les conditions le permettent ; un échec final n’est pas transformé en réussite.\n\nConserver des progrès ne fait pas agir en étant inconscient ou privé du matériel nécessaire ; aucune réserve nouvelle de PA. Une tentative entièrement résolue et échouée ne peut pas être recommencée gratuitement.","lore":"Un revers simple ne suffit plus toujours à briser une entreprise déjà lancée. Nesah conserve l’élan du personnage au travers de l’échec et lui permet de rester dans la course jusqu’à la prochaine tentative.","groupe_actuel":"Les dix Sephiroth › Nesah — Là Victoire › Facette : Succès","statut_regle":"correction","changements":"Coût 2 → 3."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_nesah_la_victoire_facette_amour_lien_du_cur', 'Lien du cœur', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 100 m","activation":"Lien consenti · 100 m","texte_court":"avec une personne consentante que tu aimes réellement, tu sens son état émotionnel général à 100 m, même sans la voir. Un lien à la fois. Ni pensées, ni position.","texte_reference":"Avec une personne consentante envers laquelle existe une affection réelle, sentez son état émotionnel général à 100 m maximum, même sans la voir. Un seul lien de ce talent est actif ; ni pensée précise ni position ne sont révélées.\n\nAucun coût d’Aura ajouté ; caractère V/SR/R conservé. Une protection spirituelle adaptée peut isoler le lien.","lore":"L’affection véritable laisse une résonance sensible pour Nesah. À proximité, l’Angelus ne lit ni pensée ni secret : il perçoit seulement l’état général du cœur auquel le sien est réellement attaché.","groupe_actuel":"Les dix Sephiroth › Nesah — Là Victoire › Facette : Amour","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_nesah_la_victoire_facette_amour_harmonie', 'Harmonie', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura, scène","activation":"1 PA · 2 Aura · scène","texte_court":"deux personnes consentantes liées par l''affection (toi compris) s''Assistent aussi en combat, à +3 au lieu de +2. Compétence et PA d''Assistance requis.","texte_reference":"Pour 1 PA et 2 Aura, deux personnes consentantes réellement liées affectivement peuvent s’Assister aussi en combat pour la scène, avec +3 au lieu de +2. Chacune doit posséder la compétence pertinente et payer le PA d’Assistance ; une seule Assistance compte par test.\n\nLes bénéficiaires peuvent inclure l’Angelus. Le talent ne fait pas agir gratuitement le partenaire et ne permet pas de cumuler Harmonie avec une Assistance équivalente.","lore":"Deux personnes liées affectivement peuvent trouver dans leur connaissance mutuelle une coordination que le stress ne détruit pas. Nesah fait de cette intimité une compréhension pratique de ce que l’autre essaie d’accomplir.","groupe_actuel":"Les dix Sephiroth › Nesah — Là Victoire › Facette : Amour","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_nesah_la_victoire_facette_amour_amour_protecteur', 'Amour protecteur', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, Réaction, 3 Aura, 1/scène","activation":null,"texte_court":"une personne que tu aimes rate une Défense occulte contre une manipulation émotionnelle ou mentale : ta Défense occulte active remplace la sienne.","texte_reference":"Lorsqu''une personne réellement aimée échoue à une Défense occulte contre une manipulation émotionnelle ou mentale, l''Angelus peut substituer sa propre Défense occulte active.","lore":"Nesah donne à l’amour la forme d’un bouclier psychique. Lorsque l’être aimé vacille sous une emprise émotionnelle ou mentale, l’Angelus peut opposer à sa place la solidité de ce lien réellement vécu.","groupe_actuel":"Les dix Sephiroth › Nesah — Là Victoire › Facette : Amour","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_nesah_la_victoire_facette_sexualite_comprehension_du_desir', 'Compréhension du désir', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Passif","texte_court":"le Détachement n''augmente plus la difficulté pour comprendre désir, attirance et intimité ; +3 pour interpréter ces motivations. Ne crée ni désir ni consentement.","texte_reference":"Supprimez la difficulté de Détachement céleste pour comprendre désir, attirance et intimité, et gagnez +3 aux tests d’interprétation de ces motivations. Cela ne provoque aucun désir ni consentement et ne révèle pas automatiquement les secrets intimes.\n\nSensibilité mortelle garde sa portée générale ; le +3 spécialisé reste utile lorsque les deux talents sont acquis. Ce n’est pas un +3 universel de séduction.","lore":"Nesah réduit la distance entre expérience céleste et désir mortel. L’Angelus comprend attirance, intimité et sensualité de l’intérieur, sans que le Détachement transforme automatiquement ces émotions en phénomène exotique à analyser.","groupe_actuel":"Les dix Sephiroth › Nesah — Là Victoire › Facette : Sexualité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_nesah_la_victoire_facette_sexualite_extase_apaisante', 'Extase apaisante', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":"b","acces":"V/SR/R","activation":"Intimité consentie","texte_court":"après une intimité réellement consentie et assez longue, la cible sort de Tendu, ou récupère 2 Aura si elle est Angelus. Une fois par scène par cible ; jamais en combat.","texte_reference":"Après une interaction intime réellement consentie et suffisamment longue, la cible peut sortir de Tendu ou récupérer 2 Aura si elle est Angelus. Une fois par scène par cible, sans geste opportuniste en combat ni dépassement du maximum d’Aura.\n\nEffet conservé ; seul le coût passe de 2 à 1 PTV. L’accès V est conservé, ce qui distingue la récupération d’Aura de l’ouverture habituelle de l’Auréole ; les causes actives de Stress et minima de blessures restent applicables.","lore":"Dans une intimité pleinement consentie, Nesah peut faire du plaisir un retour au calme plutôt qu’une simple sensation. Le temps partagé apaise ce qui était tendu et peut même rendre un peu de souffle spirituel à un autre Angelus.","groupe_actuel":"Les dix Sephiroth › Nesah — Là Victoire › Facette : Sexualité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_nesah_la_victoire_facette_sexualite_union_de_nesah', 'Union de Nesah', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R","activation":"Préparation intime consentie · prochaine scène","texte_court":"après une vraie intimité consentie, chacun des deux partenaires peut, pendant la prochaine scène, relancer un échec non narratif à un test qui protège directement l''autre. Un lien à la fois.","texte_reference":"Après une véritable intimité consentie, chacun des deux partenaires peut relancer un test ayant subi un échec non narratif pour protéger directement l’autre pendant la prochaine scène, et conserve le second résultat. Un seul lien de ce talent est actif par personne et la relance ne se cumule pas avec une autre relance de Talent.\n\nPas seulement une défense : retenir l’autre au bord d’une chute ou neutraliser son agresseur immédiat peut convenir. Une justification lointaine de protection ne rend pas tous les tests éligibles ; ni compagnon gratuit ni action supplémentaire.","lore":"Une vraie intimité crée une mémoire protectrice qui survit à la scène où elle est née. Chacun des deux partenaires emporte un instant de Nesah avec lui, prêt à se dresser lorsqu’il faudra protéger l’autre ou ce qui les unit.","groupe_actuel":"Les dix Sephiroth › Nesah — Là Victoire › Facette : Sexualité","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_hod_la_gloire', 'Carte · HOD, la Gloire', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"distinction avec Mémoire lumineuse coupée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hod_la_gloire_facette_gloire_rayonnement', 'Rayonnement', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"après une réussite publique DR 2+, ton premier test social envers un témoin vraiment impressionné gagne +3.","texte_reference":"Après une réussite publique DR 2+, le premier test social envers un témoin réellement impressionné gagne +3.","lore":"Une réussite remarquable laisse autour de l’Angelus un éclat que les témoins n’oublient pas tout de suite. Hod transforme cet instant public en crédit de présence auprès de ceux qui ont réellement été impressionnés.","groupe_actuel":"Les dix Sephiroth › Hod — La Gloire › Facette : Gloire","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hod_la_gloire_facette_gloire_heraut', 'Héraut', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura, scène","activation":"1 PA · 2 Aura · scène","texte_court":"jusqu''à trois alliés qui perçoivent ton intervention gagnent +3 contre la peur et l''intimidation. Pas de cumul avec une protection équivalente.","texte_reference":"Pour 1 PA et 2 Aura, jusqu’à trois alliés qui perçoivent votre intervention gagnent +3 contre peur et intimidation jusqu’à la fin de la scène. Une protection affective équivalente ne se cumule pas avec ce bonus.\n\nLa différence avec Foi partagée relève du Sephira et du contexte ; un personnage ne possède pas normalement les deux Sephiroth, donc ce parallèle n’exige pas une refonte artificielle.","lore":"Hod rend la présence de l’Angelus lisible comme un signe de ralliement. Ceux qui l’entendent ou le voient savent où regarder lorsque la peur cherche à disperser leurs pensées.","groupe_actuel":"Les dix Sephiroth › Hod — La Gloire › Facette : Gloire","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hod_la_gloire_facette_gloire_presence_glorieuse', 'Présence glorieuse', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":"2 PA · 3 Aura · 1/scène","texte_court":"ta présence impose une audience. Qui veut t''écarter sans t''écouter oppose sa Défense occulte à ton Charisme + Autorité. Pour la scène, +3 à tes tests sociaux envers ce public. Ni accord, ni soumission, ni fin d''un combat.","texte_reference":"Une fois par scène, pour 2 PA et 3 Aura, votre présence impose une véritable audience à un public capable de vous percevoir : ceux qui veulent vous écarter sans vous écouter opposent leur Défense occulte à votre Charisme + Autorité. Pour la scène, vos tests sociaux adressés à ce public gagnent +3, sans imposer l’accord, la soumission ou l’arrêt d’un combat.\n\nL’audience suffit à exposer une intervention cohérente, pas à retenir indéfiniment le public. Les personnes en danger immédiat peuvent se protéger et partir. C’est un renforcement surnaturel explicite ; il ne modifie pas la Renommée permanente ni les récompenses MJ.","lore":"La Gloire de Hod refuse l’insignifiance. Une fois révélée, la présence angélique demeure socialement saillante : détourner volontairement les regards devient un acte qu’il faut imposer, pas une simple facilité de conversation.","groupe_actuel":"Les dix Sephiroth › Hod — La Gloire › Facette : Gloire","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hod_la_gloire_facette_science_analyse_fonctionnelle', 'Analyse fonctionnelle', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA","activation":"1 PA · examen technique","texte_court":"après 1 PA d''observation d''un dispositif que tu sais analyser, +3 au diagnostic de sa panne ou de son point faible ; une réussite indique quel élément examiner ou manipuler. Pas de cumul avec Illumination sur le même test.","texte_reference":"Après 1 PA d’observation d’un dispositif que vos connaissances permettent réellement d’analyser, gagnez +3 au diagnostic de sa panne ou de son point faible. Une réussite indique quel élément accessible examiner ou manipuler pour confirmer ce diagnostic.\n\nPas de connaissance d’une technologie entièrement étrangère, de vision des circuits à travers les murs ou de diagnostic omniscient. Le bonus ne se cumule pas avec Illumination sur le même test ; l’intérêt supplémentaire est sa répétabilité sans Aura et l’exploitation précise du diagnostic.","lore":"Face à une machine comprise, l’Angelus de Hod en lit l’intention matérielle. Flux, mouvement et architecture révèlent ce que l’objet est censé faire et quelle partie visible porte le plus lourd de cette fonction.","groupe_actuel":"Les dix Sephiroth › Hod — La Gloire › Facette : Science","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hod_la_gloire_facette_science_optimisation', 'Optimisation', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"V/SR/R, 2 Aura, quelques minutes","activation":"Préparation · 2 Aura · scène","texte_court":"un dispositif que tu comprends donne +3 à ses usages pertinents jusqu''à la fin de la scène. Un seul à la fois.","texte_reference":"Après quelques minutes de travail et 2 Aura, un dispositif que vous comprenez confère +3 à ses utilisations pertinentes jusqu’à la fin de la scène. Vous ne pouvez maintenir qu’un dispositif optimisé à la fois ; aucune statistique permanente n’est augmentée.\n\nLe dispositif doit être réel et accessible ; le bonus concerne ses usages effectivement améliorés, pas toutes les compétences du porteur. Aucun cumul avec une amélioration équivalente et aucun effet conservé par export, rechargement ou changement de propriétaire.","lore":"Hod préfère parfois améliorer ce qui existe plutôt que créer autre chose. Quelques minutes de réglage attentif suffisent à accorder un dispositif connu à la tâche présente et à en tirer temporairement le meilleur fonctionnement possible.","groupe_actuel":"Les dix Sephiroth › Hod — La Gloire › Facette : Science","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hod_la_gloire_facette_science_solution_de_terrain', 'Solution de terrain', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"V/SR/R, 1 PA, 1/scénario","activation":"1 PA · 1/scénario","texte_court":"en 1 PA, tu assembles ou relances un outil spécialisé temporaire qui demanderait une vraie préparation. Composants, savoir et test requis ; il tient jusqu''à la fin de la scène.","texte_reference":"Une fois par scénario, assemblez ou remettez en fonctionnement en 1 PA un outil spécialisé temporaire qui demanderait normalement une véritable préparation technique. Les composants, connaissances et test technique restent requis ; l’outil fonctionne jusqu’à la fin de la scène.\n\nLe bénéfice est le temps miraculeusement gagné. Pas de matériaux créés, d’artefact, de technologie incomprise ou de marchandise revendable ; les composants réels restent ceux de l’opération.","lore":"La science de Hod excelle dans l’outil de circonstance. Avec des matériaux plausibles, l’Angelus assemble juste assez de fonction pour résoudre le besoin immédiat, bricolage inspiré dont la valeur vient précisément de son adéquation à la scène.","groupe_actuel":"Les dix Sephiroth › Hod — La Gloire › Facette : Science","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hod_la_gloire_facette_savoir_memoire_lumineuse', 'Mémoire lumineuse', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"V/SR/R","activation":null,"texte_court":"tout ce que tu as réellement appris depuis ta Transcendance revient sans erreur ordinaire.","texte_reference":"Tout ce que l''Angelus a réellement appris après sa Transcendance peut être rappelé sans erreur ordinaire.","lore":"Ce qui a été appris depuis la Transcendance peut demeurer lumineux dans la mémoire de Hod. Les détails ne se polissent pas avec le temps comme des souvenirs ordinaires : ils restent disponibles tels qu’ils furent compris.","groupe_actuel":"Les dix Sephiroth › Hod — La Gloire › Facette : Savoir","statut_regle":"correction","changements":"distinction avec Mémoire lumineuse coupée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hod_la_gloire_facette_savoir_transmission', 'Transmission', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura","activation":null,"texte_court":"tu transmets mentalement à un allié consentant une information complexe que tu maîtrises (plan, procédure, langage technique, souvenir visuel). Jamais une Compétence.","texte_reference":"Transmettre mentalement à un allié consentant une information complexe déjà maîtrisée : plan, procédure, langage technique, souvenir visuel. Ne transmet jamais une Compétence.","lore":"Hod sait transmettre une structure de pensée sans transmettre l’apprentissage qui l’a construite. Un plan, une procédure ou une image mentale passe à l’allié comme un paquet de sens déjà ordonné, prêt à être compris mais pas à remplacer son expérience.","groupe_actuel":"Les dix Sephiroth › Hod — La Gloire › Facette : Savoir","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_hod_la_gloire_facette_savoir_evidence_revelee', 'Évidence révélée', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 3 Aura, 1/scène","activation":"1 PA · 3 Aura · 1/scène","texte_court":"une déduction nouvelle, fondée sur les informations réunies, apparaît. Jusqu''à trois participants qui la comprennent gagnent +3 à leur premier test qui l''exploite. Aucun indice inventé.","texte_reference":"Une fois par scène, pour 1 PA et 3 Aura, faites apparaître une déduction nouvelle réellement fondée sur les informations réunies. Jusqu’à trois participants qui comprennent cette déduction gagnent +3 à leur premier test qui l’exploite directement pendant la scène.\n\nAucun indice inventé, secret inaccessible ou réussite automatique. La distinction avec Mémoire lumineuse est la mise en relation et la transmission exploitable, pas le simple rappel.","lore":"Lorsque toutes les pièces sont déjà connues, Hod fait apparaître le dessin qu’elles composent. Le fait décisif n’est pas créé : il devient soudain impossible à manquer dans le réseau des informations établies.","groupe_actuel":"Les dix Sephiroth › Hod — La Gloire › Facette : Savoir","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_yessod_la_fondation', 'Carte · YESSOD, la Fondation', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"« répertoire à convenir » remplacé par les trois types que le texte donnait en exemple. Idée incarnée, Forge céleste (Metatron) et Plan incarné (Aralim) restent distincts : forme fonctionnelle libre, objet manipulable, portion d''une structure étudiée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_yessod_la_fondation_facette_reves_visiteur_de_songes', 'Visiteur de songes', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":"Sommeil ou méditation · 10 m","texte_court":"pendant ton sommeil ou une longue méditation, tu rejoins le rêve d''une personne endormie et consentante à 10 m. Tu peux dialoguer, sans forcer ses souvenirs.","texte_reference":"Pendant votre sommeil ou une méditation prolongée, rejoignez le rêve d’une personne endormie et consentante à 10 m maximum. Vous pouvez y dialoguer, mais n’accédez pas de force à ses souvenirs et revenez si elle se réveille ou rompt le contact.\n\nAucun coût d’Aura ajouté ; le passage reste un échange onirique, pas une téléportation corporelle ou un moyen d’agir physiquement pendant le sommeil.","lore":"Yessod permet à deux consciences endormies de partager le même espace de rêve. L’Angelus y entre comme visiteur plutôt que comme propriétaire, présence réelle dans un paysage dont l’hôte continue de fournir la matière intime.","groupe_actuel":"Les dix Sephiroth › Yessod — La Fondation › Facette : Rêves","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_yessod_la_fondation_facette_reves_songe_dirige', 'Songe dirigé', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 2 Aura","activation":null,"texte_court":"tu glisses un message, une image ou un scénario dans le rêve d''une cible endormie (Défense occulte si elle résiste).","texte_reference":"Inserer un message, une image ou un scénario dans le rêve d''une cible endormie. Si elle résiste : Défense occulte.","lore":"L’Angelus dépose dans un rêve un morceau de récit choisi : image, phrase ou petite scène. Le dormeur l’éprouve au milieu de son propre monde onirique, sans que ce message transforme automatiquement son jugement au réveil.","groupe_actuel":"Les dix Sephiroth › Yessod — La Fondation › Facette : Rêves","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_yessod_la_fondation_facette_reves_prison_onirique', 'Prison onirique', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":"b","acces":"SR/R, 1 PA, 2 Aura, 1/scène, 20 m","activation":"1 PA · 2 Aura · 1/scène · 20 m","texte_court":"opposition occulte contre une cible déjà endormie : elle reste enfermée dans son rêve pour la scène. Un événement extérieur violent lui donne une nouvelle résistance. N''endort personne.","texte_reference":"Une fois par scène, pour 1 PA et 2 Aura, enfermez pour la scène une cible déjà endormie dans son rêve après opposition occulte. Un événement extérieur violent lui permet une nouvelle résistance pour se réveiller ; le talent n’endort pas une cible éveillée.\n\nCoût : 2 PTV au lieu de 3, 2 Aura au lieu de 3, fréquence scène au lieu de scénario ; portée 20 m. Le critère d’un effet mental profond reste possible uniquement s’il a déjà placé la cible dans un état équivalent permettant ce contact, pas une simple distraction.","lore":"Dans le sommeil déjà ouvert, Yessod peut refermer la porte vers l’éveil. Le rêve devient une chambre dont la sortie résiste, jusqu’à ce qu’un choc extérieur suffisamment réel permette à l’esprit d’en retrouver le seuil.","groupe_actuel":"Les dix Sephiroth › Yessod — La Fondation › Facette : Rêves","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_yessod_la_fondation_facette_illusion_fantasmagorie_celeste', 'Fantasmagorie céleste', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura, 20 m, scène","activation":"1 PA · 1 Aura · 20 m · scène","texte_court":"une illusion mobile, multisensorielle, de taille humaine. Qui l''examine oppose sa Perception à ton jet. Aucune force réelle.","texte_reference":"Pour 1 PA et 1 Aura, créez pour la scène une illusion extérieure mobile, multisensorielle et de taille humaine à 20 m maximum. Un observateur qui l’examine oppose sa Perception à votre jet ; elle n’exerce aucune force réelle ni dégât matériel.\n\nImage pensée conserve ses formes simples, statiques ou répétitives. Les perceptions surnaturelles adaptées s’appliquent ; voir une illusion ne donne pas automatiquement une résistance répétée à chaque seconde. Les capteurs suivent les composantes réellement simulées.","lore":"Yessod bâtit une présence fictive assez cohérente pour occuper plusieurs sens à la fois. Forme, son et mouvement s’accordent autour d’un être qui n’existe nulle part ailleurs que dans la perception qu’on lui prête.","groupe_actuel":"Les dix Sephiroth › Yessod — La Fondation › Facette : Illusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_yessod_la_fondation_facette_illusion_miroirs', 'Miroirs', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 Aura","activation":null,"texte_court":"des reflets mouvants pour la scène : +3 Défense physique contre les attaques qui doivent localiser ton corps. Qui voit à travers l''illusion ignore le bonus. Quand une attaque échoue grâce à ce +3, les reflets éclatent : l''effet prend fin.","texte_reference":"Créer plusieurs reflets mouvants autour de soi pour la scène : +3 Défense physique contre les attaques nécessitant de localiser précisément le corps. Un observateur qui voit réellement à travers l''illusion ignore le bonus.","lore":"Plusieurs silhouettes de l’Angelus glissent autour de son vrai corps et rendent la localisation incertaine. Ce n’est pas une armure : la protection existe seulement tant que l’assaillant doit encore décider lequel des reflets mérite son coup.","groupe_actuel":"Les dix Sephiroth › Yessod — La Fondation › Facette : Illusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_yessod_la_fondation_facette_illusion_monde_trompeur', 'Monde trompeur', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 3 PA, 3 Aura, 1/scène","activation":"3 PA · 3 Aura · 1/scène","texte_court":"pour la scène, l''apparence d''une zone de 10 m de rayon à 20 m change. Un seul jet de référence ; murs et créatures illusoires sans masse ni actions.","texte_reference":"Pour 3 PA et 3 Aura, une fois par scène, transformez pour la scène l’apparence perceptive d’une zone de 10 m de rayon située à 20 m maximum. Un seul jet sert de référence aux observateurs qui résistent ; les murs et créatures illusoires n’ont ni masse ni actions propres.\n\nLes détails et sens simulés restent cohérents avec Fantasmagorie céleste. Aucun double combattant, faux plancher porteur ni dégât gratuit ; les effets matériels relèvent de l’Imagination.","lore":"Yessod peut donner à tout un espace une autre apparence sensible. Architecture, lumière et présences semblent s’accorder en un monde localement mensonger, décor complet dont la faiblesse demeure qu’il doit convaincre chaque observateur.","groupe_actuel":"Les dix Sephiroth › Yessod — La Fondation › Facette : Illusion","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_yessod_la_fondation_facette_imagination_esquisse_lumineuse', 'Esquisse lumineuse', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura, scène","activation":"1 PA · 1 Aura · scène","texte_court":"une maquette lumineuse précise d''un objet ou d''un plan que tu comprends : +3 aux tests de conception, de comparaison ou de diagnostic fondés dessus. Une à la fois ; n''invente aucun détail.","texte_reference":"Pour 1 PA et 1 Aura, projetez pour la scène une maquette lumineuse précise d’un objet ou d’un plan que vous comprenez réellement. Son étude apporte +3 aux tests de conception, comparaison ou diagnostic directement fondés sur ce modèle ; une seule maquette active.\n\nLe modèle est librement dessiné et animé à portée de perception, mais il n’invente aucun détail inconnu. Il n’accorde ni bonus universel de combat ni plan parfait d’une installation jamais examinée : le bénéfice est un outil mental collectif exploitable.","lore":"L’imagination de Yessod commence comme un dessin dans l’air. Lumière et mouvement obéissent librement à l’Angelus, offrant une forme visible qui ne prétend encore ni au poids ni à la résistance.","groupe_actuel":"Les dix Sephiroth › Yessod — La Fondation › Facette : Imagination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_yessod_la_fondation_facette_imagination_idee_incarnee', 'Idée incarnée', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 2 Aura, scène","activation":"1 PA · 2 Aura · scène","texte_court":"une forme semi-solide de 3 m au plus à fonction simple (marche, corde, plateforme, petit outil). Elle porte 200 kg, a 6 PV sans Armure, n''agit pas. Jamais une prison autour d''un adversaire.","texte_reference":"Pour 1 PA et 2 Aura, créez pour la scène une forme semi-solide de 3 m maximum remplissant une fonction simple : marche, corde, plateforme ou petit outil. Elle peut soutenir jusqu’à 200 kg et possède 6 PV sans Armure ; aucune attaque ou action autonome.\n\nLa forme doit apparaître dans un espace libre et respecter la fonction définie. Un support doit posséder des ancrages cohérents ; il ne déplace pas gratuitement sa charge et ne forme pas une prison inviolable autour d’un adversaire.","lore":"Une idée simple reçoit assez de fondation pour supporter le monde. Marche, corde, plateforme ou petit outil prennent une consistance provisoire, matérialisation limitée par la fonction claire qui leur a donné naissance.","groupe_actuel":"Les dix Sephiroth › Yessod — La Fondation › Facette : Imagination","statut_regle":"correction","changements":"« répertoire à convenir » remplacé par les trois types que le texte donnait en exemple. Idée incarnée, Forge céleste (Metatron) et Plan incarné (Aralim) restent distincts : forme fonctionnelle libre, objet manipulable, portion d''une structure étudiée."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_yessod_la_fondation_facette_imagination_reve_rendu_reel', 'Rêve rendu réel', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":"2 PA · 3 Aura · 1/scène","texte_court":"un auxiliaire solide de taille humaine, mobile, voué à une seule tâche : 10 PV, Armure 3, contrôle à 30 m. Il agit avec tes PA et ta Compétence. Choisis son type à l''achat (porteur 200 kg, manipulateur simple ou rempart mobile) et note-le.","texte_reference":"Pour 2 PA et 3 Aura, une fois par scène, créez pour la scène un auxiliaire solide de taille humaine, mobile et capable d’une seule tâche définie, avec 10 PV et Armure 3. Ses actions tactiques utilisent vos PA ; il ne possède ni attaque autonome, ni pouvoir copié, ni intelligence polyvalente.\n\nRépertoire à convenir avant acquisition : porteur (charge 200 kg), manipulateur simple ou rempart mobile, par exemple. Rayon de contrôle 30 m ; mobilité normale d’un personnage, sans vol implicite. Pour une tâche incertaine, le créateur emploie sa propre Compétence pertinente, pas un profil expert inventé ; un seul auxiliaire actif, pas de PA indépendants. Les paramètres de l’auxiliaire doivent être inscrits sur la fiche.","lore":"Yessod pousse un rêve jusqu’au seuil où il devient construct. La création peut porter, bloquer ou agir selon une unique intention, mais elle n’acquiert jamais par imagination seule la complexité d’un véritable être autonome.","groupe_actuel":"Les dix Sephiroth › Yessod — La Fondation › Facette : Imagination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'angelus', 'angelus_les_dix_sephiroth_un_seul_sephira_carte_malkhouth_le_royaume', 'Carte · MALKHOUTH, le Royaume', NULL, '{"nature":"angelus","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"notes « ×4 » et téléportation coupées. Fardeau ne se cumule pas avec la Faveur Poids intérieur (Ochotiel) : les ralentissements équivalents ne s''additionnent pas."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_malkhouth_le_royaume_facette_mort_sens_du_passage', 'Sens du passage', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R","activation":null,"texte_court":"tu perçois si une créature visible est vivante, mourante ou morte, ou si son âme est séparée ou anormalement attachée au corps.","texte_reference":"Percevoir si une créature visible est vivante, mourante, morte, ou possède une âme séparée/anormalement attachée au corps.","lore":"Le Royaume permet de sentir de quel côté du seuil se trouve une présence. Vie, agonie, mort ou âme détachée ont chacune une pesanteur différente pour l’Angelus qui sait regarder le passage plutôt que le seul corps.","groupe_actuel":"Les dix Sephiroth › Malkhouth — Le Royaume › Facette : Mort","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_malkhouth_le_royaume_facette_mort_main_psychopompe', 'Main psychopompe', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 2 Aura","activation":"1 PA · 2 Aura · 10 minutes","texte_court":"auprès d''un mort récent, tu retiens son âme jusqu''à dix minutes et opposes ton jet à toute capture spirituelle. Ni résurrection, ni contrôle, ni parole forcée.","texte_reference":"Pour 1 PA et 2 Aura auprès d’un mort récent, retenez son âme jusqu’à dix minutes et opposez votre jet aux tentatives de capture spirituelle. Cela n’accorde ni résurrection, ni contrôle, ni accès automatique au retour d’un Daemon vers sa Divinité ou d’un Angelus vers l’Arbre.\n\nLa rétention ne fait pas parler automatiquement l’âme et n’empêche pas toute puissance supérieure d’intervenir. Fenêtre de dix minutes ; aucun revenu d’Aura ni conservation illimitée.","lore":"Auprès d’un mort récent, l’Angelus se tient comme gardien du seuil. Il peut empêcher qu’une autre puissance arrache précipitamment l’âme à son chemin, sans pour autant renverser les lois propres au Cycle, à l’Arbre ou aux anciennes Divinités.","groupe_actuel":"Les dix Sephiroth › Malkhouth — Le Royaume › Facette : Mort","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_malkhouth_le_royaume_facette_mort_fauche_du_royaume', 'Fauche du Royaume', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":null,"texte_court":"attaque occulte DGT 12 contre une entité incorporelle, une âme séparée ou une créature vivante à 25 % de ses PV ou moins.","texte_reference":"Attaque occulte DGT 12 contre entité incorporelle, âme séparée ou créature vivante à 25 % PV ou moins.","lore":"Malkhouth connaît les frontières du vivant aussi sûrement que celles de la matière. Sa faux spirituelle trouve les êtres déjà proches du passage ou ceux qui existent sans corps, là où une attaque purement physique chercherait en vain une prise.","groupe_actuel":"Les dix Sephiroth › Malkhouth — Le Royaume › Facette : Mort","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_malkhouth_le_royaume_facette_monde_physique_masse_choisie', 'Masse choisie', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"R, 1 Aura","activation":null,"texte_court":"pour la scène, ton corps devient très léger (+3 sauts, équilibre, chutes) ou très lourd (+3 contre déplacement et renversement).","texte_reference":"Pour la scène, rendre son corps très léger ou très lourd. Léger : +3 sauts/équilibre/chutes. Lourd : +3 contre déplacement/renversement. Aucun bonus de dégâts.","lore":"Le corps de Malkhouth peut se choisir un rapport différent au poids. Léger, il épouse les sauts et les équilibres ; lourd, il s’enracine dans le sol, deux manières opposées d’affirmer la même maîtrise de la matière.","groupe_actuel":"Les dix Sephiroth › Malkhouth — Le Royaume › Facette : Monde physique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_malkhouth_le_royaume_facette_monde_physique_densite', 'Densité', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 2 Aura, scène","activation":"1 PA · 2 Aura · scène","texte_court":"Armure corporelle 3 contre les dégâts physiques. Elle s''ajoute à une armure portée, mais pas à une autre Armure corporelle : seule la meilleure compte.","texte_reference":"Pour 1 PA et 2 Aura, votre corps gagne Armure corporelle 3 contre les dégâts physiques jusqu’à la fin de la scène. Elle se cumule avec une Armure portée compatible, mais seule la meilleure couche corporelle s’applique.\n\nLa durée de scène est le renforcement ; le cumul corporel/porté applique la règle commune explicite. Pas de cumul avec une autre Armure corporelle 3/4/6 ni de réduction des PV sacrifiés.","lore":"Malkhouth rappelle que le Royaume est aussi matière. L’Angelus épaissit sa présence physique jusqu’à donner à sa chair une densité presque minérale, capable d’absorber un choc qui aurait autrement traversé le corps.","groupe_actuel":"Les dix Sephiroth › Malkhouth — Le Royaume › Facette : Monde physique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_malkhouth_le_royaume_facette_monde_physique_realite_verrouillee', 'Réalité verrouillée', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène","activation":"2 PA · 3 Aura · 1/scène","texte_court":"une zone de 10 m de rayon, ancrée pour la scène. Devenir intangible ou se téléporter dans, vers ou hors de la zone exige de battre ton jet d''installation, alliés compris. N''annule pas une intangibilité déjà active ; ne bloque pas l''invisibilité.","texte_reference":"Pour 2 PA et 3 Aura, une fois par scène, ancrez une zone de 10 m de rayon jusqu’à la fin de la scène. Devenir intangible ou se téléporter dans, vers ou hors de cette zone demande de vaincre votre jet d’installation, alliés compris.\n\nN’annule pas une intangibilité déjà active, ne force pas une créature à prendre un corps et ne bloque pas l’invisibilité. Bina conserve le choix de l’invisibilité ; Malkhouth ancre les deux procédés de déplacement incorporel. Une réussite adverse autorise sa tentative sans détruire tout le champ.","lore":"Le Royaume impose à l’espace une stabilité presque obstinée. Dans cette zone, disparaître hors du monde matériel ou sauter ailleurs n’est plus un mouvement naturel : il faut d’abord vaincre la réalité que Malkhouth maintient fermée.","groupe_actuel":"Les dix Sephiroth › Malkhouth — Le Royaume › Facette : Monde physique","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_malkhouth_le_royaume_facette_poids_fardeau', 'Fardeau', NULL, '{"nature":"angelus","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"SR/R, 1 PA, 1 Aura, 20 m","activation":"1 PA · 1 Aura · 20 m","texte_court":"Volonté + Maîtrise spirituelle contre Défense occulte : Déplacement divisé par deux et −3 aux tests de mobilité jusqu''à la fin de son prochain round.","texte_reference":"Pour 1 PA et 1 Aura, opposez Volonté + Maîtrise spirituelle à la Défense occulte d’une cible : ses déplacements sont divisés par deux et ses tests de mobilité subissent −3 jusqu’à la fin de son prochain round. Les ralentissements équivalents ne se multiplient pas.\n\nPortée 20 m ; aucun dégât automatique, immobilisation totale ou interdiction de téléportation.","lore":"Malkhouth charge la cible d’un poids qui se traduit d’abord dans chaque tentative de bouger. Les jambes paraissent travailler contre une gravité personnelle, et même les gestes simples réclament soudain un effort disproportionné.","groupe_actuel":"Les dix Sephiroth › Malkhouth — Le Royaume › Facette : Poids","statut_regle":"correction","changements":"notes « ×4 » et téléportation coupées. Fardeau ne se cumule pas avec la Faveur Poids intérieur (Ochotiel) : les ralentissements équivalents ne s''additionnent pas."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_malkhouth_le_royaume_facette_poids_ecrasement', 'Écrasement', NULL, '{"nature":"angelus","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"R, 1 PA, 2 Aura","activation":null,"texte_court":"attaque directe contre Défense occulte, DGT 9 : un poids brutal s''abat.","texte_reference":"Attaque directe contre Défense occulte, DGT 9, manifestee comme une augmentation brutale de poids.","lore":"La masse n’augmente pas progressivement : elle tombe. La cible éprouve d’un coup l’impression d’être tirée vers le bas par un monde devenu trop lourd pour elle seule.","groupe_actuel":"Les dix Sephiroth › Malkhouth — Le Royaume › Facette : Poids","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'les_dix_sephiroth_malkhouth_le_royaume_facette_poids_poids_du_royaume', 'Poids du Royaume', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"R, 2 PA, 3 Aura, 1/scène, 30 m","activation":"2 PA · 3 Aura · 1/scène","texte_court":"une zone de 10 m de rayon s''alourdit pour la scène. Les ennemis qui ratent l''opposition occulte voient leur Déplacement divisé par deux et ne peuvent plus gagner d''altitude. Un seul jet d''installation.","texte_reference":"Pour 2 PA et 3 Aura, une fois par scène, alourdissez pour la scène une zone de 10 m de rayon à 30 m maximum. Les ennemis qui échouent à l’opposition occulte voient leurs déplacements divisés par deux et ne peuvent plus gagner d’altitude dans la zone, sans chute ou dégât automatiques.\n\nUn seul jet d’installation, pas de nouvelle attaque gratuite à chaque round. Les obstacles réellement produits affectent le terrain ; ne pas cumuler un même ralentissement en ×4. Le talent n’interdit ni téléportation ni passage intangible, rôle de Réalité verrouillée.","lore":"Le poids du Royaume descend sur toute une zone et rappelle aux corps qu’ils appartiennent au sol. Sauts, course et vol deviennent laborieux, comme si l’espace lui-même résistait à tout ce qui veut s’élever ou traverser trop vite.","groupe_actuel":"Les dix Sephiroth › Malkhouth — Le Royaume › Facette : Poids","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'angelus', 'progression_de_transcendance_transcendance_cherubique', 'Transcendance chérubique', NULL, '{"nature":"angelus","cout":3,"cout_actuel":3,"palier":null,"porte":null,"hors_voie":true,"acces":"Progression · Progression · 3 PTV préalables de Nature","activation":"Progression · 3 PTV préalables de Nature","texte_court":"Après au moins 3 PTV investis dans votre Nature primaire et l’événement narratif requis, obtenez le rang Chérubin et choisissez une seconde Nature. Vous recevez son pouvoir fondamental et l’accès à ses talents, avec +2 au bonus et au plafond d’Aura de rang.","texte_reference":"Après au moins 3 PTV investis dans votre Nature primaire et l’événement narratif requis, obtenez le rang Chérubin et choisissez une seconde Nature. Vous recevez son pouvoir fondamental et l’accès à ses talents, avec +2 au bonus et au plafond d’Aura de rang.\n\nPas de nouvelle Sephira, de nouvel Archange ou de Séraphin standard. Les deux paires d’ailes ne donnent toujours que +1 Agilité au total. Les 3 PTV préalables ne comprennent pas les talents communs ou ceux du Sephira. Le prérequis narratif doit rester un accord réel, non une approbation fabriquée par le formulaire.","lore":"La Transcendance chérubique marque une véritable seconde naissance dans l’Arbre. Une nouvelle paire d’ailes et une seconde Nature apparaissent parce que l’Angelus a assez approfondi sa première voie pour supporter une expression céleste plus large.","groupe_actuel":"Progression de Transcendance","statut_regle":"origine","changements":"Laissé hors des voies par le lot (moteur, maîtrise ou rang)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
